// Box — the generic styled container primitive (#2079). The catch-all so features never write a raw
// `<div>`: every arbitrary styled/plain wrapper (a padded panel, a positioned overlay, a bordered
// box, a className-only div) becomes a `<Box>`. Stack/Row/Grid stay the choice for flex/grid layout,
// Text for text, Card for framed panels — Box is everything else.
//
// Moderate token-backed shorthands (`pad`/`bg`/`border`/`radius`/`shadow`) cover the high-frequency
// inline styles; anything else goes through `style` (which wins last). Polymorphic via `as` (default
// div; e.g. section/aside/ul/span). Any extra prop (className, onClick, data-*, ref-free DOM attrs)
// passes straight through.

import type { CSSProperties, ReactNode, ElementType, ComponentPropsWithoutRef } from "react";
import { pad as padValue, type Space } from "./space";

/** Corner radius — a token rung (--r-*) or raw px. */
export type Radius = "sm" | "md" | "lg" | number;
/** Elevation — a --shadow-* rung. */
export type Shadow = "sm" | "md" | "lg" | "xl";
/** Border — true → --stroke, "soft" → --stroke-soft, or a color string → `1px solid <color>`. */
export type BorderProp = boolean | "soft" | string;

const RADIUS: Record<"sm" | "md" | "lg", string> = { sm: "var(--r-sm)", md: "var(--r-md)", lg: "var(--r-lg)" };

function radiusValue(r: Radius | undefined): string | undefined {
  if (r == null) return undefined;
  return typeof r === "number" ? `${r}px` : RADIUS[r];
}

function borderValue(b: BorderProp | undefined): string | undefined {
  if (b == null || b === false) return undefined;
  if (b === true) return "var(--stroke)";
  if (b === "soft") return "var(--stroke-soft)";
  return `1px solid ${b}`;
}

export interface BoxProps extends Omit<ComponentPropsWithoutRef<"div">, "children"> {
  children?: ReactNode;
  /** The rendered element (default "div"; e.g. section/aside/ul/span). */
  as?: ElementType;
  /** Inner padding — a space rung/px, or a [block, inline] pair. */
  pad?: Space | [Space, Space];
  /** Background color/token (e.g. "var(--bg-elev)"). */
  bg?: string;
  /** Border — true → --stroke, "soft" → --stroke-soft, or a color → `1px solid <color>`. */
  border?: BorderProp;
  /** Corner radius — a rung (sm/md/lg → --r-*) or raw px. */
  radius?: Radius;
  /** Drop shadow — a --shadow-* rung (sm/md/lg/xl). */
  shadow?: Shadow;
  style?: CSSProperties;
}

export function Box({ children, as: As = "div", pad, bg, border, radius, shadow, style, ...rest }: BoxProps) {
  const p = padValue(pad);
  const b = borderValue(border);
  const r = radiusValue(radius);
  return (
    <As
      style={{
        ...(p != null ? { padding: p } : {}),
        ...(bg != null ? { background: bg } : {}),
        ...(b != null ? { border: b } : {}),
        ...(r != null ? { borderRadius: r } : {}),
        ...(shadow != null ? { boxShadow: `var(--shadow-${shadow})` } : {}),
        ...style,
      }}
      {...rest}
    >
      {children}
    </As>
  );
}

// Stack — a vertical flex column with a gap (#2056). The one primitive for the ~200 hand-rolled
// `<div style={{ display: "flex", flexDirection: "column", gap: N }}>` divs across the app.
//
// Cross-axis default is the native `stretch` (align left unset), so converting an existing column
// div is lossless — pass `align` only when the div set `alignItems`. Any extra div prop (className,
// onClick, data-*, role, …) passes straight through, and a `style` override wins last.

import type { ReactNode, CSSProperties, ComponentPropsWithoutRef } from "react";
import { flexStyle, pad, type Space, type Align, type Justify } from "./space";

export interface StackProps extends Omit<ComponentPropsWithoutRef<"div">, "children"> {
  children?: ReactNode;
  /** Gap between children — a scale rung ("sm"/"md"/…) or raw px. */
  gap?: Space;
  /** Cross-axis (horizontal) alignment. Default = native `stretch`. */
  align?: Align;
  /** Main-axis (vertical) distribution. */
  justify?: Justify;
  /** Allow wrapping (rare for a column, but supported). */
  wrap?: boolean;
  /** Inner padding — a single `Space` (all sides) or `[block, inline]`. */
  pad?: Space | [Space, Space];
  /** Render as `inline-flex` instead of `flex`. */
  inline?: boolean;
  style?: CSSProperties;
}

export function Stack({ children, gap, align, justify, wrap, pad: p, inline, style, ...rest }: StackProps) {
  return (
    <div
      style={{
        display: inline ? "inline-flex" : "flex",
        flexDirection: "column",
        ...flexStyle({ gap, align, justify, wrap }),
        ...(p != null ? { padding: pad(p) } : {}),
        ...style,
      }}
      {...rest}
    >
      {children}
    </div>
  );
}

// Row — a horizontal flex row with a gap (#2056). The one primitive for the ~150 hand-rolled
// `<div style={{ display: "flex", alignItems: "center", gap: N }}>` divs across the app.
//
// Cross-axis default is `center` (the dominant intent for a row of controls/labels) — pass
// `align="baseline"`/`"start"`/… for the others, or `align="stretch"` for the bare `flex + gap`
// case that set no `alignItems`. Pair with <Spacer/> to push trailing items to the end. Any extra
// div prop passes through; a `style` override wins last.

import type { ReactNode, CSSProperties, ComponentPropsWithoutRef } from "react";
import { flexStyle, pad, type Space, type Align, type Justify } from "./space";

export interface RowProps extends Omit<ComponentPropsWithoutRef<"div">, "children"> {
  children?: ReactNode;
  /** Gap between children — a scale rung ("sm"/"md"/…) or raw px. */
  gap?: Space;
  /** Cross-axis (vertical) alignment. Default = `center`. */
  align?: Align;
  /** Main-axis (horizontal) distribution. */
  justify?: Justify;
  /** Allow items to wrap onto multiple lines. */
  wrap?: boolean;
  /** Inner padding — a single `Space` (all sides) or `[block, inline]`. */
  pad?: Space | [Space, Space];
  /** Render as `inline-flex` instead of `flex`. */
  inline?: boolean;
  style?: CSSProperties;
}

export function Row({ children, gap, align = "center", justify, wrap, pad: p, inline, style, ...rest }: RowProps) {
  return (
    <div
      style={{
        display: inline ? "inline-flex" : "flex",
        ...flexStyle({ gap, align, justify, wrap }),
        ...(p != null ? { padding: pad(p) } : {}),
        ...style,
      }}
      {...rest}
    >
      {children}
    </div>
  );
}

// Spacer — flexible or fixed empty space inside a Row/Stack (#2056). Replaces the ~40 hand-rolled
// `<div style={{ flex: 1 }} />` fillers that push trailing items to the far end of a row.
//
//   <Row>  <h3>Title</h3>  <Spacer/>  <Button/>  </Row>   → button pinned right
//   <Row>  a  <Spacer size="md"/>  b  </Row>              → a fixed 12px gap between a and b
//
// A fixed spacer (`size`) reserves a rigid box along the parent's main axis; the default
// (sizeless) spacer greedily absorbs the remaining space.

import type { CSSProperties } from "react";
import { space, type Space } from "./space";

export interface SpacerProps {
  /** A rigid spacer of this size (scale rung or raw px). Omit for a flexible (`flex:1`) spacer. */
  size?: Space;
  style?: CSSProperties;
}

export function Spacer({ size, style }: SpacerProps) {
  if (size != null) {
    const n = space(size);
    // `flex: 0 0 <n>` sizes it along the parent's main axis regardless of row/column direction.
    return <div aria-hidden style={{ flex: `0 0 ${n}px`, ...style }} />;
  }
  return <div aria-hidden style={{ flex: 1, ...style }} />;
}

// Grid — a CSS grid container with template tracks and a gap (#2058). The one primitive for the
// ~77 hand-rolled `<div style={{ display: "grid", gridTemplateColumns: …, gap: N }}>` divs across
// the app. The common templates are `1fr 1fr` (9×), `repeat(N, 1fr)`, `1fr auto`, and bespoke pixel
// tracks — so `cols` takes EITHER a number `n` (→ `repeat(n, 1fr)`, the even-split shorthand) OR an
// explicit template string passed straight through (`"1fr auto"`, `"50px 1fr auto 50px"`).
//
// Alignment reuses the shared layout vocabulary (`space.ts`): `align` → `alignItems` (cell cross-axis
// alignment) and `justify` → `justifyContent` (inline-axis track distribution, so the full Justify
// vocabulary incl. between/around/evenly is valid). Any extra div prop (className, onClick,
// data-*, …) passes straight through, and a `style` override wins last — so mechanical
// `<div style>` → `<Grid>` conversions stay lossless.

import type { ReactNode, CSSProperties, ComponentPropsWithoutRef } from "react";
import { space, alignValue, justifyValue, type Space, type Align, type Justify } from "./space";

/** A track spec: a number `n` (→ `repeat(n, 1fr)`) or an explicit template string (passed through). */
type Tracks = number | string;

function tracks(v: Tracks | undefined): string | undefined {
  if (v == null) return undefined;
  return typeof v === "number" ? `repeat(${v}, 1fr)` : v;
}

export interface GridProps extends Omit<ComponentPropsWithoutRef<"div">, "children"> {
  children?: ReactNode;
  /** Columns — a number `n` (even `repeat(n, 1fr)` split) or an explicit `gridTemplateColumns` string. */
  cols?: Tracks;
  /** Rows — a number `n` (even `repeat(n, 1fr)` split) or an explicit `gridTemplateRows` string. */
  rows?: Tracks;
  /** Gap between cells — a scale rung ("sm"/"md"/…) or raw px. */
  gap?: Space;
  /** Cross-axis (block) item alignment → `alignItems`. */
  align?: Align;
  /** Inline-axis track distribution → `justifyContent`. */
  justify?: Justify;
  /** Render as `inline-grid` instead of `grid`. */
  inline?: boolean;
  style?: CSSProperties;
}

export function Grid({ children, cols, rows, gap, align, justify, inline, style, ...rest }: GridProps) {
  const g = space(gap);
  return (
    <div
      style={{
        display: inline ? "inline-grid" : "grid",
        ...(cols != null ? { gridTemplateColumns: tracks(cols) } : {}),
        ...(rows != null ? { gridTemplateRows: tracks(rows) } : {}),
        ...(g != null ? { gap: g } : {}),
        ...(align ? { alignItems: alignValue(align) } : {}),
        ...(justify ? { justifyContent: justifyValue(justify) } : {}),
        ...style,
      }}
      {...rest}
    >
      {children}
    </div>
  );
}

import type { ReactNode, CSSProperties } from "react";
import "./sectionHeader.css";

export interface SectionHeaderProps {
  title: ReactNode;
  /** Dimmed inline sub-text after the title. */
  hint?: ReactNode;
  /** Right-aligned dim mono text (e.g. a count) — wrapped in the meta style. */
  meta?: ReactNode;
  /** Right-aligned raw content (e.g. a search input or button) — overrides `meta`. */
  right?: ReactNode;
  titleStyle?: CSSProperties;
  className?: string;
}

/** SectionHeader — the one uppercase section-title row: `title · hint · spacer · meta|right`.
 *  Absorbs the agents/mcp `.sec-head` (#1874). Planner's collapsible `.sec-head` (chev/count/hover)
 *  is a different component and is intentionally left alone. */
export function SectionHeader({ title, hint, meta, right, titleStyle, className }: SectionHeaderProps) {
  return (
    <div className={"section-header" + (className ? ` ${className}` : "")}>
      <h3 style={titleStyle}>{title}</h3>
      {hint != null && <span className="hint">{hint}</span>}
      {(right != null || meta != null) && <span className="sh-spacer" />}
      {right != null ? right : meta != null ? <span className="sh-meta">{meta}</span> : null}
    </div>
  );
}

import type { CSSProperties, ReactNode } from "react";

export interface SectionLabelProps {
  children: ReactNode;
  /** `md` (default): 10px / .06em — the common section/kv label. `sm`: 9px / .08em — the tighter
   *  caption used in dense KPI/analytics tiles. A raw px number is also legal (dense .08em tracking) —
   *  e.g. `size={9.5}`, the legacy `.ulabel` size (#2420). */
  size?: "sm" | "md" | number;
  /** `dim` (default, var(--fg-dim)) or `muted` (var(--fg-muted)). */
  tone?: "dim" | "muted";
  /** Optional right-aligned slot (#2420) — renders a space-between label row (label · right), the
   *  repeated "section header with a trailing note/control" idiom. `style` then styles the ROW. */
  right?: ReactNode;
  className?: string;
  style?: CSSProperties;
}

/** The uppercase mono micro-label — `fontFamily:var(--mono)` + `textTransform:uppercase` +
 *  letter-spacing + a dim/muted color — hand-rolled ~75× across the app. Collapses the four
 *  boilerplate style props into one primitive while keeping per-site spacing via `style` (#1837). */
export function SectionLabel({ children, size = "md", tone = "dim", right, className, style }: SectionLabelProps) {
  const label: CSSProperties = {
    fontSize: typeof size === "number" ? size : size === "sm" ? 9 : 10,
    letterSpacing: size === "md" ? ".06em" : ".08em",
    textTransform: "uppercase",
    color: tone === "muted" ? "var(--fg-muted)" : "var(--fg-dim)",
  };
  if (right == null) {
    return (
      <div className={`${className ?? ""} mono`} style={{ ...label, ...style }}>
        {children}
      </div>
    );
  }
  return (
    <div className={className} style={{ display: "flex", alignItems: "center", justifyContent: "space-between", gap: 8, ...style }}>
      <div className="mono" style={label}>{children}</div>
      {right}
    </div>
  );
}

import { ModalScrim } from "./ModalScrim";

interface DialogProps {
  title: string;
  children: React.ReactNode;
  actions: React.ReactNode;
  onDismiss: () => void;
  danger?: boolean;
}

export function Dialog({ title, children, actions, onDismiss, danger }: DialogProps) {
  return (
    <ModalScrim onDismiss={onDismiss}>
      <div
        className="card"
        style={{
          minWidth: 360, maxWidth: 500, padding: "22px 24px",
          boxShadow: "0 8px 32px oklch(0 0 0 / 0.5)",
          borderColor: danger ? "var(--danger)" : undefined,
        }}
      >
        <h3 className="mono" style={{
          margin: "0 0 10px", fontSize: 14, fontWeight: 600,
          color: danger ? "var(--danger)" : "var(--fg)",
        }}>
          {title}
        </h3>
        <div style={{ color: "var(--fg-muted)", fontSize: 12, lineHeight: 1.6, marginBottom: 20 }}>
          {children}
        </div>
        <div style={{ display: "flex", gap: 8, justifyContent: "flex-end" }}>
          {actions}
        </div>
      </div>
    </ModalScrim>
  );
}

// ModalScrim (#1776) — the ONE centered-modal overlay. Fixed full-screen scrim (the `--scrim`
// token) at the `--z-modal` layer, flex-centering its child card, with Escape + overlay-click
// dismiss. Every modal/dialog renders its card inside this instead of hand-rolling a fixed overlay
// with a per-file scrim colour and z-index. `<Dialog>` is built on it; custom-bodied modals wrap
// their own card with it.
//
//  - onDismiss: called on Escape and on a click/mousedown that lands on the scrim itself (not the
//    card). Pass `undefined` to make the modal non-dismissable (e.g. while a destructive op is busy).
//  - align="start" top-aligns the card (for tall, scrolling modals); default centers it.
//  - blur adds the backdrop blur some modals used.
import { type ReactNode, type CSSProperties } from "react";
import { useModalDismiss, overlayDismiss } from "@/shared/hooks/useModalDismiss";

export function ModalScrim({ children, onDismiss, align = "center", blur = false, className = "", style }: {
  children: ReactNode;
  onDismiss?: () => void;
  align?: "center" | "start";
  blur?: boolean;
  className?: string;
  style?: CSSProperties;
}) {
  useModalDismiss(() => onDismiss?.(), { enabled: !!onDismiss });
  const cls = ["modal-scrim", align === "start" ? "start" : "", blur ? "blur" : "", className].filter(Boolean).join(" ");
  return (
    <div className={cls} onMouseDown={overlayDismiss(onDismiss)} style={style}>
      {children}
    </div>
  );
}

// ModalCard (#2420) — the titled head/body/foot modal card over ModalScrim, extracted from the four
// hand-rolled copies (blueprint import, MCP download, kit share, session skills). One canonical
// chrome: a bg-panel card (border · --r-lg · --shadow-xl · overflow hidden) with
//   head — optional IconBox glyph · mono title (+ dim sub) · optional headExtra rows · ✕ close
//   body — the scrollable content (padding 20 by default; override via bodyStyle for list layouts)
//   foot — an optional bordered action row.
// `<Dialog>` stays the lighter confirm/short-form card; ModalCard is for the richer titled modals.
//
//  - onClose wires BOTH the head ✕ and the scrim's Escape/overlay-click dismiss; omit it for a
//    non-dismissable modal. `busy` keeps the ✕ visible but disabled and suppresses scrim dismiss
//    (a destructive/long-running op in flight).
import type { CSSProperties, ReactNode } from "react";
import { ModalScrim } from "./ModalScrim";
import { IconBox } from "@/shared/ui/data/IconBox";
import { IconButton } from "@/shared/ui/controls/IconButton";
import { Row } from "@/shared/ui/layout/Row";
import { Box } from "@/shared/ui/layout/Box";
import { Text } from "@/shared/ui/typography/Text";

export interface ModalCardProps {
  title: ReactNode;
  /** Dim sub-line under the title. */
  sub?: ReactNode;
  /** Leading head glyph, rendered in a 30px IconBox (accent-tinted by default). */
  icon?: ReactNode;
  iconBackground?: string;
  iconColor?: string;
  /** Wires the head ✕ + Escape + scrim-click. Omit for a non-dismissable modal. */
  onClose?: () => void;
  /** Keep the ✕ but disable it and suppress scrim/Escape dismiss (an op in flight). */
  busy?: boolean;
  /** Card width (default 540). Always capped at maxWidth:100% of the padded scrim. */
  width?: number | string;
  /** Card max height (default "88vh"). */
  maxHeight?: string;
  /** Scrim card alignment — `start` top-aligns tall scrolling modals. */
  align?: "center" | "start";
  /** Backdrop blur (default true — the titled modals all used it). */
  blur?: boolean;
  /** Extra head rows under the title row (search/tabs/meta), inside the bordered head block. */
  headExtra?: ReactNode;
  /** Footer action row content; omitted → no foot. */
  foot?: ReactNode;
  /** Merged onto the body (padding/overflow overrides for list-style bodies). */
  bodyStyle?: CSSProperties;
  /** Merged onto the foot row (e.g. a darker footer bg). */
  footStyle?: CSSProperties;
  /** aria-label for the dialog card (defaults to the title when it is a string). */
  ariaLabel?: string;
  className?: string;
  children: ReactNode;
}

export function ModalCard({
  title, sub, icon, iconBackground, iconColor, onClose, busy = false,
  width = 540, maxHeight = "88vh", align, blur = true, headExtra, foot,
  bodyStyle, footStyle, ariaLabel, className, children,
}: ModalCardProps) {
  const dismiss = onClose && !busy ? onClose : undefined;
  return (
    <ModalScrim onDismiss={dismiss} align={align} blur={blur} style={{ padding: 30, ...(align === "start" ? { overflow: "auto" } : {}) }}>
      <Box
        className={className}
        role="dialog"
        aria-label={ariaLabel ?? (typeof title === "string" ? title : undefined)}
        style={{
          width, maxWidth: "100%", maxHeight,
          display: "flex", flexDirection: "column",
          background: "var(--bg-panel)", border: "1px solid var(--border)",
          borderRadius: "var(--r-lg)", boxShadow: "var(--shadow-xl)", overflow: "hidden",
        }}
      >
        <Box className="modal-head" style={{ padding: "16px 20px", borderBottom: "1px solid var(--border-soft)", flex: "none" }}>
          <Row gap={11}>
            {icon != null && (
              <IconBox size={30} radius={7} fontSize={13}
                background={iconBackground ?? "color-mix(in oklch, var(--accent), transparent 84%)"}
                color={iconColor ?? "var(--accent)"}>{icon}</IconBox>
            )}
            <Box style={{ minWidth: 0 }}>
              <Text as="h2" mono size="lg" weight={600} style={{ margin: 0 }}>{title}</Text>
              {sub != null && <Text as="div" size={10.5} tone="dim" style={{ marginTop: 1 }}>{sub}</Text>}
            </Box>
            {onClose && (
              <IconButton aria-label="close" style={{ marginLeft: "auto" }} onClick={onClose} disabled={busy} />
            )}
          </Row>
          {headExtra}
        </Box>
        <Box className="modal-body" style={{ padding: 20, overflowY: "auto", ...bodyStyle }}>{children}</Box>
        {foot != null && (
          <Row gap={9} className="modal-foot" style={{ padding: "14px 20px", borderTop: "1px solid var(--border-soft)", flex: "none", ...footStyle }}>
            {foot}
          </Row>
        )}
      </Box>
    </ModalScrim>
  );
}

// Text — the one typographic primitive (#2057). Collapses the hand-rolled text-styling triad
// spread across the app: the ~1,100 inline `fontSize:` props, the ~945 inline `color:` props, and
// the 558 `className="mono"` sites — into one `<Text size tone mono weight>`.
//
// Every prop is opt-in and lossless: `size` takes a named rung ("sm"/"md"/…) OR a raw px number
// (the off-scale half-sizes stay reachable), `tone` is a SEMANTIC color enum (never a raw token),
// `mono` toggles the existing `mono` utility class (not an inline font-family). With no props it is
// a bare `<span>` that forces no size, color, or weight — so wrapping existing text never changes
// it. Any extra prop (onClick, title, htmlFor when as="label", data-*, …) passes straight through,
// and a `style` override wins last.

import type { CSSProperties, ReactNode, ElementType } from "react";
import { fontSize, toneColor, type TextSize, type Tone } from "./type";
import { Skeleton } from "@/shared/ui/feedback/Skeleton";

export interface TextProps {
  children?: ReactNode;
  /** Font size — a scale rung ("sm"/"md"/…) or raw px. Omit to inherit. */
  size?: TextSize;
  /** Semantic color tone ("dim"/"muted"/"accent"/"danger"/"success"). Omit to inherit. */
  tone?: Tone;
  /** Add the `mono` utility class (JetBrains Mono) rather than an inline font-family. */
  mono?: boolean;
  /** Font weight — a number (500/600/…) or a CSS keyword ("bold"/…). */
  weight?: CSSProperties["fontWeight"];
  /** The rendered element (default `"span"`; e.g. div/p/label/h1–h4). */
  as?: ElementType;
  /** Render LOADING (#2302): an inline shimmer line the height of the text. `loadingWidth` sets px width. */
  loading?: boolean;
  loadingWidth?: number | string;
  className?: string;
  style?: CSSProperties;
  /** Any other prop passes through to the rendered element. */
  [key: string]: unknown;
}

export function Text({ children, size, tone, mono, weight, as: As = "span", loading, loadingWidth, className, style, ...rest }: TextProps) {
  const fs = fontSize(size);
  const color = toneColor(tone);
  if (loading) {
    const h = typeof fs === "number" ? Math.round(fs) : 11;
    return <Skeleton w={loadingWidth ?? 72} h={h} radius={4} style={{ display: "inline-block", verticalAlign: "middle", ...style }} />;
  }
  return (
    <As
      className={mono ? `${className ?? ""} mono`.trim() : className}
      style={{
        ...(fs != null ? { fontSize: fs } : {}),
        ...(color != null ? { color } : {}),
        ...(weight != null ? { fontWeight: weight } : {}),
        ...style,
      }}
      {...rest}
    >
      {children}
    </As>
  );
}

