import type { ButtonHTMLAttributes } from "react";

export interface ButtonProps extends ButtonHTMLAttributes<HTMLButtonElement> {
  /** Background style — the `.btn` family. `default` = the quiet bg-elev secondary · `primary` =
   *  the accent call-to-action · `ghost` = transparent. A DATA-DEFINED variant (#2569, authored via
   *  `bsc ui component btn define-variant`) is any other lowercase string: it rides the same
   *  class-name path (`.btn.<variant>`) that `applyVariantsToRoot`'s compiled CSS targets. */
  variant?: "default" | "primary" | "ghost" | (string & {});
  /** Danger color modifier (composes with `default`/`ghost`). */
  danger?: boolean;
  /** Hit size: `md` = 28px (default) · `sm` = 24px. */
  size?: "md" | "sm";
}

/**
 * The shared button primitive (#1889) — a thin wrapper over the `.btn` class system in
 * `tokens.css`, so it rides the exact styles the app already ships (no visual divergence) and
 * stays the one place button look is defined. Reach for this instead of a hand-rolled
 * `<button style={{…}}>` or a CSSProperties helper. For icon-only buttons use `IconButton`; for the
 * back-chevron use `BackButton`. All native `<button>` attributes (onClick, disabled, title, type,
 * style for one-off positional tweaks, …) pass through.
 */
export function Button({
  variant = "default", danger, size = "md", className, type = "button", ...rest
}: ButtonProps) {
  const cls = ["btn", variant !== "default" && variant, danger && "danger", size === "sm" && "sm", className]
    .filter(Boolean)
    .join(" ");
  return <button type={type} className={cls} {...rest} />;
}

// IconButton (#1753) — the one button for icon-glyph actions (close / remove / cancel), replacing the
// five wrappers (`.x`, the misspelled-and-unstyled `.iconbtn`, `.btn ghost` at three sizes, `.mini`,
// fully-inline) and two glyphs (`×` U+00D7 vs `✕` U+2715) the app had hand-rolled. Renders the
// canonical close glyph by default; `aria-label` is REQUIRED so every icon button is accessible.
import type { ReactNode, CSSProperties, MouseEvent } from "react";

/** The one canonical close/dismiss glyph. */
export const CLOSE_GLYPH = "✕";

export interface IconButtonProps {
  /** Required — icon buttons have no text, so they must carry an accessible name. */
  "aria-label": string;
  onClick?: (e: MouseEvent<HTMLButtonElement>) => void;
  /** The glyph/icon; defaults to the canonical close glyph. */
  children?: ReactNode;
  /** Hit-area size: md = 24px (default, modal/panel/banner headers) · sm = 20px · xs = 16px (inline chip removers). */
  size?: "md" | "sm" | "xs";
  /** Red hover (destructive). */
  danger?: boolean;
  disabled?: boolean;
  title?: string;
  className?: string;
  style?: CSSProperties;
}

export function IconButton({
  "aria-label": ariaLabel, onClick, children, size = "md", danger, disabled, title, className, style,
}: IconButtonProps) {
  const cls = ["icon-btn", size !== "md" && size, danger && "danger", className].filter(Boolean).join(" ");
  return (
    <button type="button" className={cls} aria-label={ariaLabel} title={title ?? ariaLabel} onClick={onClick} disabled={disabled} style={style}>
      {children ?? CLOSE_GLYPH}
    </button>
  );
}

import type { KeyboardEvent } from "react";

export interface CheckboxProps {
  checked: boolean;
  /** When provided, the box is self-interactive (click + Space/Enter, `role="checkbox"`). Omit when a
   *  parent row already owns the toggle — the box is then presentational and the row handles the click. */
  onChange?: () => void;
  /** Box edge in px (default 14). The ✓ scales with it. */
  size?: number;
  disabled?: boolean;
  className?: string;
  "aria-label"?: string;
}

/**
 * The shared checkbox primitive (#1891) — the small ✓ square consolidated from the hand-rolled
 * `<span style={{…}}>` copies (skills facets + card select). Sibling to `Toggle` (pill switch) and
 * `SegmentedControl`. Presentational by default (a parent row toggles); pass `onChange` to make the
 * box itself interactive + keyboard-operable.
 */
export function Checkbox({ checked, onChange, size = 14, disabled, className, "aria-label": ariaLabel }: CheckboxProps) {
  const interactive = !!onChange && !disabled;
  const onKeyDown = interactive
    ? (e: KeyboardEvent) => { if (e.key === " " || e.key === "Enter") { e.preventDefault(); onChange!(); } }
    : undefined;
  return (
    <span
      className={className}
      role={interactive ? "checkbox" : undefined}
      aria-checked={interactive ? checked : undefined}
      aria-label={ariaLabel}
      tabIndex={interactive ? 0 : undefined}
      onClick={interactive ? () => onChange!() : undefined}
      onKeyDown={onKeyDown}
      style={{
        width: size, height: size, flex: "0 0 auto", borderRadius: 4,
        border: "1px solid " + (checked ? "var(--accent)" : "var(--border)"),
        background: checked ? "var(--accent)" : "transparent",
        color: "var(--bg-canvas)", fontSize: Math.round(size * 0.64),
        display: "flex", alignItems: "center", justifyContent: "center",
        cursor: interactive ? "pointer" : undefined, opacity: disabled ? 0.4 : undefined,
      }}
    >
      {checked ? "✓" : ""}
    </span>
  );
}

// A pill switch (#1527) — consolidates the toggle copied across settings, skills, and the planner
// deploy/integration bodies. Three sizes preserve the (drifted) call sites exactly: "md" (32×18, the
// settings panels), "sm" (26×15, the skills rows + planner deploy/integration toggles), and "xs"
// (24×14, the compact Integrations "tools available to agents" grid, #1779). `tone` picks the
// ON-state color: "accent" (default) or "success" (the green deploy/integration toggles — a
// translucent track with a solid success border + knob). The track lights when `on`; the knob
// slides right.

import type { MouseEvent } from "react";

interface ToggleProps {
  on: boolean;
  onClick?: (e: MouseEvent) => void;
  /** "md" (32×18, default — settings panels), "sm" (26×15, skills rows), or "xs" (24×14, compact grids). */
  size?: "xs" | "sm" | "md";
  /** ON-state color: "accent" (default) or "success" (green). */
  tone?: "accent" | "success";
  className?: string;
  role?: string;
  ariaChecked?: boolean;
}

export function Toggle({ on, onClick, size = "md", tone = "accent", className, role, ariaChecked }: ToggleProps) {
  const success = tone === "success";
  // ON-state colors by tone. accent (default) is byte-identical to the original component; success
  // reproduces the green deploy/integration toggles (translucent track + solid success border/knob).
  const trackOn = success ? "color-mix(in oklch, var(--success), transparent 50%)" : "var(--accent)";
  const borderOn = success ? "var(--success)" : "transparent";
  const borderOff = success ? "var(--border-soft)" : "var(--border)";

  // "sm" (26×15 / 11px knob) and "xs" (24×14 / 10px knob) share the absolute-knob track; only the
  // track/knob dimensions and the ON knob offset differ.
  if (size === "sm" || size === "xs") {
    const xs = size === "xs";
    const w = xs ? 24 : 26;
    const h = xs ? 14 : 15;
    const knob = xs ? 10 : 11;
    return (
      <span
        className={className}
        onClick={onClick}
        role={role}
        aria-checked={ariaChecked}
        style={{
          width: w, height: h, borderRadius: 99, position: "relative", flex: "0 0 auto",
          cursor: onClick ? "pointer" : "default",
          background: on ? trackOn : "var(--bg-elev2)",
          border: "1px solid " + (on ? borderOn : borderOff),
        }}
      >
        <span style={{
          position: "absolute", top: 1, left: on ? w - knob - 3 : 1, width: knob, height: knob, borderRadius: "50%",
          background: on ? (success ? "var(--success)" : "var(--bg-canvas)") : "var(--fg-dim)",
        }} />
      </span>
    );
  }
  return (
    <span
      className={className}
      onClick={onClick}
      role={role}
      aria-checked={ariaChecked}
      style={{
        display: "inline-flex", alignItems: "center",
        width: 32, height: 18, borderRadius: 99, cursor: "pointer",
        background: on ? trackOn : "var(--bg-elev2)",
        border: "1px solid " + (on ? borderOn : borderOff),
        transition: "background 0.15s", flex: "0 0 auto",
      }}
    >
      <span style={{
        width: 12, height: 12, borderRadius: "50%",
        background: on ? (success ? "var(--success)" : "#1a120a") : "var(--fg-dim)",
        marginLeft: on ? "auto" : 2, marginRight: on ? 2 : "auto",
        transition: "margin 0.15s",
      }} />
    </span>
  );
}

import type { ReactNode } from "react";
import "./segmentedControl.css";

export interface SegOption {
  label: ReactNode;
  /** Whether this option is currently active. */
  on: boolean;
  onClick: () => void;
  /** On-state colour. Default "accent". */
  tone?: "accent" | "allow" | "ask" | "deny";
  /** Show a leading dot in the current colour. */
  dot?: boolean;
  title?: string;
}

export interface SegmentedControlProps {
  options: SegOption[];
  /** "padded" (default) = gapped pill buttons in a padded container; "joined" = a tight shared-border bar. */
  variant?: "padded" | "joined";
  /** Button height: "sm" (22px, default) or "md" (24px). */
  size?: "sm" | "md";
  /** Optional leading label (e.g. "scope"). */
  label?: ReactNode;
  className?: string;
}

/** SegmentedControl — the one mutually-exclusive / multi-toggle button group: the control-vocabulary
 *  primitive that absorbs `.scope` · `.seg` · `.tri` · `.pill-group` (#1874). Each option owns its
 *  on-state + click, so it serves single-select and multi-select alike; `tone` covers the
 *  allow/ask/deny tri-states. */
export function SegmentedControl({ options, variant = "padded", size = "sm", label, className }: SegmentedControlProps) {
  return (
    <div className={"seg-ctl" + (className ? ` ${className}` : "")}>
      {label != null && <span className="seg-ctl-label">{label}</span>}
      <div className={`seg-grp ${variant} size-${size}`}>
        {options.map((o, i) => (
          <button
            key={i}
            type="button"
            title={o.title}
            className={"seg-btn tone-" + (o.tone ?? "accent") + (o.on ? " on" : "")}
            onClick={o.onClick}
          >
            {o.dot && <span className="seg-dot" />}
            {o.label}
          </button>
        ))}
      </div>
    </div>
  );
}

