// One canonical back control (#1752) — replaces the ad-hoc text-arrow "←" strings that were scattered
// across the planner. Always renders the `chevron_left` SVG (never the literal "←"), so every back
// affordance looks the same.
//
//   variant="icon"  — a boxed 30×30 chevron button (the planner-header design). `label` is ignored.
//   variant="text"  — a chevron + text label (e.g. "portfolio", "fleet", "back"). The call site keeps
//                     its own look by passing `className`/`style` (e.g. "nav-btn", "btn ghost", or the
//                     inline header-link style); this component only standardizes the glyph + layout.
import type { CSSProperties } from "react";
import { Ic } from "@/shared/ui/icons";

interface BackButtonProps {
  onClick: () => void;
  /** Required — back buttons must be screen-reader labelled (the bare chevron isn't). */
  "aria-label": string;
  variant?: "icon" | "text";
  /** Text-variant label rendered after the chevron. */
  label?: string;
  disabled?: boolean;
  className?: string;
  style?: CSSProperties;
  /** Chevron px size (defaults: 18 for icon, 14 for text). */
  size?: number;
  title?: string;
}

export function BackButton({
  onClick, "aria-label": ariaLabel, variant = "text", label, disabled, className, style, size, title,
}: BackButtonProps) {
  if (variant === "icon") {
    return (
      <button
        type="button"
        onClick={onClick}
        disabled={disabled}
        aria-label={ariaLabel}
        title={title ?? ariaLabel}
        className={className}
        style={{
          width: 30, height: 30, flex: "0 0 30px",
          display: "inline-flex", alignItems: "center", justifyContent: "center",
          background: "var(--bg-elev)", border: "1px solid var(--border)",
          borderRadius: "var(--r-md)", cursor: "pointer",
          color: "var(--fg)", padding: 0, marginRight: 2,
          ...style,
        }}
      ><Ic n="chevron_left" size={size ?? 18} /></button>
    );
  }
  return (
    <button
      type="button"
      onClick={onClick}
      disabled={disabled}
      aria-label={ariaLabel}
      title={title}
      className={className}
      style={{ display: "inline-flex", alignItems: "center", gap: 4, ...style }}
    >
      <Ic n="chevron_left" size={size ?? 14} />
      {label}
    </button>
  );
}

import type { CSSProperties } from "react";

export interface ColorSwatchProps {
  /** The fill colour — any CSS colour, incl. `var()` / `color-mix()`. */
  color: string;
  /** Square side in px. Default 9. */
  size?: number;
  /** Corner radius in px. Default 2. */
  radius?: number;
  className?: string;
  style?: CSSProperties;
}

/** ColorSwatch — the small rounded colour square used as a category / profile / legend indicator.
 *  Replaces the inline `<span style={{ width:9, height:9, borderRadius:2, background }} />` repeated
 *  across the app. `flex:0 0` keeps it from shrinking inside flex rows. */
export function ColorSwatch({ color, size = 9, radius = 2, className, style }: ColorSwatchProps) {
  return (
    <span
      className={className}
      style={{ display: "inline-block", width: size, height: size, borderRadius: radius, background: color, flex: `0 0 ${size}px`, ...style }}
    />
  );
}

// A two-step confirm button (#1527) — first click arms it (turns red), the second click within
// the same focus fires; blur disarms so a stray click is safe. Consolidates the copies across the
// settings panels. Two sizes preserve the call sites: "md" (8×14, alignSelf flex-start) and "sm"
// (5×10, inline). `danger` (default) styles it red; `disabled` dims + blocks it.

import { useState, type CSSProperties } from "react";

interface ConfirmButtonProps {
  label: string;
  armedLabel: string;
  onConfirm: () => void | Promise<void>;
  /** "md" (8×14, the reset cards) — the default — or "sm" (5×10, the inline list-row actions). */
  size?: "sm" | "md";
  disabled?: boolean;
  danger?: boolean;
  style?: CSSProperties;
}

export function ConfirmButton({
  label, armedLabel, onConfirm, size = "md", disabled = false, danger = true, style,
}: ConfirmButtonProps) {
  const [armed, setArmed] = useState(false);
  const sm = size === "sm";
  return (
    <button
      className="mono"
      disabled={disabled}
      onClick={() => { if (armed) { setArmed(false); void onConfirm(); } else { setArmed(true); } }}
      onBlur={() => setArmed(false)}
      style={{
        ...(sm ? {} : { alignSelf: "flex-start" }),
        padding: sm ? "5px 10px" : "8px 14px",
        borderRadius: 6,
        cursor: disabled ? "default" : "pointer",
        fontSize: sm ? 10.5 : 11.5,
        ...(disabled ? { opacity: 0.5 } : {}),
        background: armed && danger ? "var(--danger)" : "var(--bg-elev)",
        color: armed && danger ? "var(--bg-canvas)" : danger ? "var(--danger)" : "var(--fg)",
        border: "1px solid " + (armed && danger
          ? "var(--danger)"
          : danger ? "color-mix(in oklch, var(--danger), transparent 55%)" : "var(--border)"),
        ...style,
      }}
    >{armed ? armedLabel : label}</button>
  );
}

// Card — the one framed-panel primitive (#card-unify). Renders the shared `.card` class (bg-panel +
// 1px border + rounded corners + padding, from tokens.css) so it's a drop-in for the ~100 raw
// `<div className="card">` divs across the app — feature CSS that targets `.card` as an ancestor
// (`.card .head`, `.prof-list.card`, …) keeps working untouched. On top of the class it adds a thin
// layer: an optional canonical head (`title` + `hint` + `right` → an h3 row, absorbing the old
// `SettingsCardHead`) OR a fully-custom `header` node, a `tone` border tint, an `interactive`/`onClick`
// hover affordance, and a compact `pad="sm"` density. Layout cards still add their own className.
import type { ReactNode, CSSProperties, MouseEvent } from "react";
import { SkeletonText } from "@/shared/ui/feedback/Skeleton";

export interface CardProps {
  children: ReactNode;
  /** Render the card LOADING (#2302): keep the frame + head, replace the body with a skeleton the
   *  same shape as its content. `loadingLines` tunes the body skeleton's line count (default 3). */
  loading?: boolean;
  loadingLines?: number;
  /** Canonical head: a title (h3) rendered above the body. The one-stop "card with a title". */
  title?: ReactNode;
  /** Inline hint beside the title (canonical head only). */
  hint?: ReactNode;
  /** Right-aligned control in the canonical head row. */
  right?: ReactNode;
  /** Override the canonical head's bottom margin (px). Default 12. */
  headMb?: number;
  /** A fully-composed header node — for heads that aren't the canonical h3 row. Wins over `title`. */
  header?: ReactNode;
  /** Border accent color — e.g. "var(--accent)" / "var(--success)". Default = the `.card` border. */
  tone?: string;
  /** Hover/press affordance (pointer + a transition); also implied when `onClick` is set. */
  interactive?: boolean;
  /** "sm" overrides `.card`'s padding for a compact body card; default keeps the `.card` look. */
  pad?: "sm";
  className?: string;
  style?: CSSProperties;
  onClick?: (e: MouseEvent<HTMLDivElement>) => void;
  /** The HTML `title` attribute (hover tooltip). */
  tooltip?: string;
}

export function Card({ children, loading, loadingLines = 3, title, hint, right, headMb, header, tone, interactive, pad, className, style, onClick, tooltip }: CardProps) {
  const head = header ?? (title != null ? (
    <div style={{ display: "flex", alignItems: "baseline", marginBottom: headMb ?? 12, gap: 10 }}>
      <h3 style={{ margin: 0 }}>{title}</h3>
      {hint && <span className="hint">{hint}</span>}
      {right && <><span style={{ flex: 1 }} />{right}</>}
    </div>
  ) : null);
  return (
    <div
      className={"card" + (className ? ` ${className}` : "")}
      title={tooltip}
      onClick={onClick}
      style={{
        ...(tone ? { borderColor: `color-mix(in oklch, ${tone}, transparent 72%)` } : {}),
        ...(interactive || onClick ? { cursor: "pointer", transition: "border-color .1s, background .1s" } : {}),
        ...(pad === "sm" ? { padding: "10px 12px" } : {}),
        ...style,
      }}
    >
      {head}
      {loading ? <SkeletonText lines={loadingLines} /> : children}
    </div>
  );
}

components.srcText:
export function Chip({ tone = "neutral", color, dot, children }: ChipProps) {
  if (color) return <span style={mix(color)}>{children}</span>;
  return <span className={`chip tone-${tone}`}>{children}</span>;
}

components.source:
// Chip — the shared "mono color-mix pill" (#1713): a small inline-flex badge whose own text
// `color` drives a translucent color-mix background + border. This is the one chip skeleton that
// was re-declared verbatim across the planner bodies (the connector-form InfoChip + the legitimacy
// ClearChip); it lives here once and the named variants delegate to it.
//
// Deliberately NOT folded in (folding would change their rendering — see #1635):
//   • ModeChip   — mixes a DIFFERENT oklch color than its text color.
//   • EntityChip / TypeChip — solid fills with `borderRadius: 4` (not 99), no color-mix.
//   • mcp scopeChips — className-based (`tag`/`ptag`) multi-element helper, not an inline pill.
// Those stay local to their feature.

import type { ReactNode, CSSProperties } from "react";
import { Skeleton } from "@/shared/ui/feedback/Skeleton";
import "./chip.css";

const MONO = "var(--mono)";

export type ChipTone = "neutral" | "accent" | "success" | "info" | "danger";

/** Chip — the one pill (#1874). Two paths:
 *  - `tone` (default): a semantic class-based pill (theme-able via chip.css) — absorbs `.tag` + the
 *    feature badges (mode/origin/…).
 *  - `color`: the translucent color-mix pill rendered inline — for DYNAMIC colours (GitHub labels,
 *    profile colours). Overrides `tone`; the original Chip behaviour, preserved. */
export function Chip({
  children,
  tone = "neutral",
  color,
  dot,
  size = "sm",
  title,
  className,
  style,
  bgAlpha = 88,
  borderAlpha = 72,
  gap = 6,
  padding,
  radius = 99,
  fontSize,
  alignSelf,
  loading,
  loadingWidth,
}: {
  children: ReactNode;
  /** Render the chip LOADING (#2302): a shimmer pill the shape of a chip. `loadingWidth` sets its px width. */
  loading?: boolean;
  loadingWidth?: number;
  /** Semantic tone (class-based). Ignored when `color` is set. */
  tone?: ChipTone;
  /** An explicit colour — renders the inline color-mix pill (dynamic colours). Overrides `tone`. */
  color?: string;
  /** A leading dot in the current colour. */
  dot?: boolean;
  /** "xs" (8.5px) · "sm" (10px, default, = the old `.tag`) · "md" (10.5px). */
  size?: "xs" | "sm" | "md";
  title?: string;
  className?: string;
  style?: CSSProperties;
  // ── inline `color`-path knobs (the dynamic-colour pill) ──
  bgAlpha?: number;
  borderAlpha?: number;
  gap?: number;
  padding?: string;
  radius?: number;
  fontSize?: number;
  alignSelf?: "flex-start" | "center" | "flex-end" | "stretch";
}) {
  if (loading) {
    const h = size === "md" ? 18 : size === "xs" ? 15 : 17;
    return <Skeleton w={loadingWidth ?? 48} h={h} radius={radius} style={{ display: "inline-block", verticalAlign: "middle", alignSelf, ...style }} />;
  }
  if (color) {
    return (
      <span title={title} className={className} style={{
        display: "inline-flex", alignSelf, alignItems: "center", gap, fontFamily: MONO,
        fontSize: fontSize ?? 9.5, color,
        background: `color-mix(in oklch, ${color}, transparent ${bgAlpha}%)`,
        border: `1px solid color-mix(in oklch, ${color}, transparent ${borderAlpha}%)`,
        borderRadius: radius, padding: padding ?? "3px 9px", ...style,
      }}>
        {dot && <span style={{ width: 5, height: 5, borderRadius: "50%", background: color, flex: "0 0 5px" }} />}
        {children}
      </span>
    );
  }
  return (
    <span title={title} style={style} className={`chip tone-${tone} size-${size}` + (className ? ` ${className}` : "")}>
      {dot && <span className="chip-dot" />}
      {children}
    </span>
  );
}

/** Map a legacy `.tag` modifier class (green/amber/info/danger) to a Chip tone. */
export function tagTone(cls?: string): ChipTone {
  return cls === "green" ? "success" : cls === "amber" ? "accent" : cls === "info" ? "info" : cls === "danger" ? "danger" : "neutral";
}

import type { ReactNode, CSSProperties } from "react";
import { Card } from "./Card";
import { Skeleton } from "@/shared/ui/feedback/Skeleton";
import "./statTile.css";

export interface StatTileProps {
  /** The uppercase label. */
  k: ReactNode;
  /** The big value. */
  v: ReactNode;
  /** Optional sub-text under the value. */
  sub?: ReactNode;
  /** Value colour tone. */
  tone?: "success" | "accent" | "danger";
  /** An explicit value style (e.g. a dynamic colour) — overrides `tone`. */
  vStyle?: CSSProperties;
  /** Render the value (and sub) as shimmer placeholders while the metric's source loads (#2234). */
  loading?: boolean;
  className?: string;
}

/** StatTile — the one metric tile: a card with an uppercase label (`k`), a big value (`v`), and an
 *  optional `sub`. Replaces the `.card` + `.k`/`.v`/`.sub` idiom whose styling was re-declared per
 *  feature (`.summary`, `.hist-summary`, …); the value tone maps to a colour. */
export function StatTile({ k, v, sub, tone, vStyle, loading, className }: StatTileProps) {
  return (
    <Card className={"stat-tile" + (className ? ` ${className}` : "")}>
      <div className="k">{k}</div>
      {loading
        ? <div className="v"><Skeleton h={20} w={56} radius={5} style={{ margin: "3px 0" }} /></div>
        : <div className={"v" + (tone ? ` ${tone}` : "")} style={vStyle}>{v}</div>}
      {sub != null && (
        <div className="sub">{loading ? <Skeleton h={9} w={72} radius={4} /> : sub}</div>
      )}
    </Card>
  );
}

import type { CSSProperties } from "react";
import { Skeleton } from "@/shared/ui/feedback/Skeleton";
import { clamp } from "@/shared/lib/core/math";

export interface FillBarProps {
  /** Fill fraction 0..1 (clamped). */
  value: number;
  /** Render LOADING (#2302): the track shimmers indeterminately instead of a fixed fill. */
  loading?: boolean;
  /** Fill color. Default `var(--accent)`. */
  color?: string;
  /** Track (background) color. Default `var(--bg-elev2)`. */
  track?: string;
  /** Bar height in px. Default 8. */
  height?: number;
  /** Pill radius (99) when true (default), square when false. */
  rounded?: boolean;
  className?: string;
  /** Applied to the track element (e.g. flex sizing in a multi-segment row). */
  style?: CSSProperties;
}

/** A horizontal track with an inner width-driven fill — the progress/allocation bar hand-rolled
 *  across the analytics tabs, contributor lists, and planner deploy/scan views (#1838). Compose
 *  several side-by-side for a multi-segment bar. */
export function FillBar({ value, loading, color = "var(--accent)", track = "var(--bg-elev2)", height = 8, rounded = true, className, style }: FillBarProps) {
  const pct = clamp(value, 0, 1) * 100;
  const radius = rounded ? 99 : 0;
  if (loading) return <Skeleton w="100%" h={height} radius={radius} style={{ ...style }} />;
  return (
    <div className={className} style={{ height, borderRadius: radius, background: track, overflow: "hidden", ...style }}>
      <div style={{ height: "100%", width: `${pct}%`, background: color, borderRadius: radius }} />
    </div>
  );
}

// Code — the one read-only monospace code/prompt block (#2102). A tiny framed `<pre>` that bakes in
// the "preStyle" recipe re-declared verbatim across the app (the kickoff-prompt preview + lane-context
// blocks in the focused agent editor, and their kin): a scrollable, mono, muted, canvas-tinted panel.
//
// It is DISPLAY-ONLY — it renders text/JSON/logs, never a syntax-highlighted or interactive block
// (per-line diffs, the crash boundary's kit-free `<pre>`, and file viewers keep their own markup).
// Every prop is opt-in: `maxHeight` caps the scroll height, `wrap` toggles soft-wrapping (on) vs a
// horizontal scroll (`whiteSpace: "pre"`), `tone` picks the foreground color, and `className`/`style`
// pass through with `style` winning last so any single value stays overridable.

import type { CSSProperties, ReactNode } from "react";
import { toneColor, type Tone } from "../typography/type";
import { SkeletonText } from "@/shared/ui/feedback/Skeleton";

export interface CodeProps {
  children?: ReactNode;
  /** Render LOADING (#2302): shimmer lines inside the code frame. `loadingLines` tunes the count (default 4). */
  loading?: boolean;
  loadingLines?: number;
  /** Max scroll height in px before the block scrolls (default 150). */
  maxHeight?: number;
  /** Soft-wrap long lines (`pre-wrap`, default) vs a horizontal scroll (`pre`). */
  wrap?: boolean;
  /** Foreground color tone (default "muted" → var(--fg-muted)). */
  tone?: Tone;
  className?: string;
  style?: CSSProperties;
}

export function Code({ children, loading, loadingLines = 4, maxHeight = 150, wrap = true, tone = "muted", className, style }: CodeProps) {
  return (
    <pre
      className={className}
      style={{
        margin: 0,
        maxHeight,
        overflow: "auto",
        whiteSpace: wrap ? "pre-wrap" : "pre",
        wordBreak: "break-word",
        fontFamily: "var(--mono)",
        fontSize: 10,
        lineHeight: 1.5,
        color: toneColor(tone),
        background: "var(--bg-canvas)",
        border: "1px solid var(--border-soft)",
        borderRadius: 5,
        padding: "8px 9px",
        ...style,
      }}
    >
      {loading ? <SkeletonText lines={loadingLines} lineH={9} /> : children}
    </pre>
  );
}

// A round GitHub user avatar (#1493) — the initial on a login-hashed color. Consolidates the
// byte-identical copies that lived in GitHubSummary / ProjectsSummary (summary feeds) and the
// palette/ring variant in the planner Issues / ProjectBoard assignee stacks.
//
// NOTE: the chart/fleet avatar with the `bot` ◆ glyph is a DIFFERENT component, kept in
// ui/charts/primitives.tsx — it renders agent glyphs, not GitHub logins.

import { loginColor } from "@/shared/lib/core/format";
import { avatarColor } from "@/shared/lib/github/colors";

interface AvatarProps {
  login: string;
  size?: number;
  /** Use the discrete AVATAR_PALETTE (assignee stacks) instead of the continuous loginColor hue. */
  palette?: boolean;
  /** The 1.5px canvas ring used so overlapping avatars read as separate disks. */
  bordered?: boolean;
  /** Horizontal offset — negative for overlapping assignee stacks. */
  ml?: number;
  /** Font size as a fraction of `size` (default 0.5; the assignee stacks use 0.56). */
  fontScale?: number;
}

export function Avatar({ login, size = 20, palette = false, bordered = false, ml, fontScale = 0.5 }: AvatarProps) {
  return (
    <span title={"@" + login} className="mono" style={{
      width: size, height: size, borderRadius: "50%",
      background: palette ? avatarColor(login) : loginColor(login), color: "#1a120a",
      fontWeight: 700, fontSize: size * fontScale,
      display: "flex", alignItems: "center", justifyContent: "center", flexShrink: 0,
      ...(ml ? { marginLeft: ml } : {}),
      ...(bordered ? { border: "1.5px solid var(--bg-canvas)" } : {}),
    }}>{login[0]?.toUpperCase() ?? "?"}</span>
  );
}

// IconBox — the centered fixed-size icon/glyph square repeated across the planner modals + cards
// (#1882). Dedups the width/height/flex/center/border-radius boilerplate; size, radius, background,
// color, and the optional glyph styling (fontSize / fontWeight / border) stay props. Renders `mono`
// so a letter/glyph child sits right (an <Icon> component child is unaffected).
import type { ReactNode, CSSProperties } from "react";

export function IconBox({
  size = 30, radius = 7, background, color, fontSize, fontWeight = 700, border, className, style, children,
}: {
  size?: number;
  radius?: number;
  background?: string;
  color?: string;
  fontSize?: number;
  fontWeight?: number;
  /** A full `border` shorthand (e.g. `1px solid …`). */
  border?: string;
  className?: string;
  style?: CSSProperties;
  children: ReactNode;
}) {
  return (
    <span
      className={className}
      style={{
        width: size, height: size, flex: `0 0 ${size}px`,
        display: "flex", alignItems: "center", justifyContent: "center",
        borderRadius: radius, fontFamily: "var(--mono)", fontWeight,
        ...(fontSize != null ? { fontSize } : {}),
        ...(background != null ? { background } : {}),
        ...(color != null ? { color } : {}),
        ...(border != null ? { border } : {}),
        ...style,
      }}
    >
      {children}
    </span>
  );
}

import type { ReactNode, CSSProperties } from "react";
import "./cardListRow.css";

export interface CardListRowProps {
  /** The 18px lead column — a status dot, icon, or avatar. */
  lead?: ReactNode;
  /** Primary label. */
  title: ReactNode;
  /** A pill rendered next to the title (left of the spacer). */
  badge?: ReactNode;
  /** A right-aligned element on the title line — a control or badge pushed to the right. */
  titleAside?: ReactNode;
  /** Secondary line under the title. */
  subtitle?: ReactNode;
  /** Full-width rich content below the header line (e.g. a wrapping chip list). */
  body?: ReactNode;
  /** The trailing (auto-width) column — chips, counts, controls, a toggle. */
  trailing?: ReactNode;
  /** Selection highlight. */
  selected?: boolean;
  /** Dimmed/disabled look. */
  off?: boolean;
  /** "card" (default) = bordered card; "grouped" = no border, top-separator, inherits the parent bg. */
  variant?: "card" | "grouped";
  /** A left-rail accent colour, shown when the row is `selected` (e.g. a profile colour). */
  accent?: string;
  onClick?: () => void;
  className?: string;
}

/** CardListRow — the selectable card-list row: a `[lead · title+badge / subtitle · trailing]` bordered
 *  card. The card-list archetype of the row vocabulary (#1865); its sibling is <DataTableRow> for
 *  columnar tables. Every card-list (mcp servers/hooks, agent profiles, …) composes this with its own
 *  slot content, so the kit/SDK emits one row shape rather than N bespoke rows. */
export function CardListRow({ lead, title, badge, titleAside, subtitle, body, trailing, selected, off, variant = "card", accent, onClick, className }: CardListRowProps) {
  return (
    <div
      className={
        "card-list-row" +
        (variant === "grouped" ? " grouped" : "") +
        (body != null ? " has-body" : "") +
        (accent != null ? " has-accent" : "") +
        (onClick ? " clickable" : "") +
        (selected ? " selected" : "") +
        (off ? " off" : "") +
        (className ? ` ${className}` : "")
      }
      style={accent != null ? ({ ["--clr-accent" as string]: accent } as CSSProperties) : undefined}
      onClick={onClick}
    >
      <div className="clr-lead">{lead}</div>
      <div className="clr-main">
        <div className="clr-line1">
          <span className="clr-name">{title}</span>
          {badge}
          {titleAside != null && <><span className="clr-spacer" />{titleAside}</>}
        </div>
        {subtitle != null && <div className="clr-desc">{subtitle}</div>}
        {body != null && <div className="clr-body">{body}</div>}
      </div>
      {trailing != null && <div className="clr-aside">{trailing}</div>}
    </div>
  );
}

import type { ReactNode } from "react";
import "./dataTable.css";

export interface DataTableHeaderProps {
  /** grid-template-columns — pass the SAME value as the rows so labels align over their columns. */
  template: string;
  /** The column-label cells. */
  children: ReactNode;
  className?: string;
}

/** DataTableHeader — the sticky column header for a <DataTableRow> table. */
export function DataTableHeader({ template, children, className }: DataTableHeaderProps) {
  return (
    <div className={"dt-header" + (className ? ` ${className}` : "")} style={{ gridTemplateColumns: template }}>
      {children}
    </div>
  );
}

export interface DataTableRowProps {
  /** grid-template-columns — shared with the <DataTableHeader> so cells align under their labels. */
  template: string;
  /** The cell content, one node per column. */
  children: ReactNode;
  /** Row index — when provided, odd rows get a zebra-stripe background. */
  index?: number;
  selected?: boolean;
  off?: boolean;
  onClick?: () => void;
  /** Fixed row height in px (default 37 via CSS). */
  height?: number;
  className?: string;
  /** Extra attributes spread onto the row element — e.g. `{ "data-skill-id": id }` for targeting. */
  attrs?: Record<string, string | number>;
}

/** DataTableRow — one columnar row of a data table: the columnar archetype of the row vocabulary
 *  (#1865; sibling: CardListRow). A shared `template` with the <DataTableHeader> aligns the columns;
 *  the row supplies zebra striping + hover + selection chrome. Cell content is the caller's, so any
 *  table (skills library, agent assignments, …) composes ONE row primitive rather than a bespoke one. */
export function DataTableRow({ template, children, index, selected, off, onClick, height, className, attrs }: DataTableRowProps) {
  return (
    <div
      className={
        "dt-row" +
        (selected ? " selected" : "") +
        (off ? " off" : "") +
        (index != null && index % 2 ? " odd" : "") +
        (className ? ` ${className}` : "")
      }
      style={{ gridTemplateColumns: template, ...(height != null ? { height: `${height}px` } : {}) }}
      onClick={onClick}
      {...attrs}
    >
      {children}
    </div>
  );
}

// RoleTierChips (#2420) — a session role's capability tiers (git · github · code · net) as colored
// mono pills: the permission floor a persona/position inherits. Extracted from the duplicate pair
// (personas `RoleTiers` / org `TierChips`) so both features render the same clearance row.
import { Row } from "@/shared/ui/layout/Row";
import { Chip } from "@/shared/ui/data/Chip";
import { roleCapability, type SessionRole } from "@/shared/lib/session/sessionRoles";

/** Tier → pill color: write = accent (mutating), read = info, none = dim. */
const TIER_COLOR: Record<string, string> = { none: "var(--fg-dim)", read: "var(--info)", write: "var(--accent)" };

export interface RoleTierChipsProps {
  /** The session role whose capability floor to render. */
  role: SessionRole;
}

/** The four capability tiers of a role, as coloured pills — the permission floor a persona inherits. */
export function RoleTierChips({ role }: RoleTierChipsProps) {
  const cap = roleCapability(role);
  const tiers: [string, string][] = [["git", cap.git], ["github", cap.github], ["code", cap.code], ["net", cap.net]];
  return (
    <Row gap={5} wrap>
      {/* One template-literal text node — `{k} · {v}` renders three nodes, which breaks exact-text queries. */}
      {tiers.map(([k, v]) => <Chip key={k} color={TIER_COLOR[v] ?? "var(--fg-dim)"}>{`${k} · ${v}`}</Chip>)}
    </Row>
  );
}

// Shared analytics card + control primitives (#399), ported from
// design/fleet-github-skills/js/shell.jsx. Used alongside the SVG charts on the
// Fleet / Repo Pulse analytics pages.
import { useState, useCallback, type ReactNode, type CSSProperties } from "react";
import type { ChartTip } from "./Charts";
import { loginColor } from "@/shared/lib/core/format";
import { Skeleton } from "@/shared/ui/feedback/Skeleton";

/** Compact number formatter (e.g. 1234 → "1.2k", 12000 → "12k"). */
export function fmt(n: number): string {
  return n >= 1000 ? (n / 1000).toFixed(n >= 10000 ? 0 : 1) + "k" : String(n);
}

export type StatTone = "fg" | "accent" | "info" | "success" | "danger";
interface StatCardProps {
  k: string;
  v: ReactNode;
  sub?: ReactNode;
  tone?: StatTone;
  delta?: { dir: "up" | "down" | "flat"; text: string };
  /** Render the value (and sub) as shimmer placeholders while the metric's source loads (#2234). */
  loading?: boolean;
}
export function StatCard({ k, v, sub, tone, delta, loading }: StatCardProps) {
  const color =
    tone === "accent" ? "var(--accent)" : tone === "info" ? "var(--info)" :
    tone === "success" ? "var(--success)" : tone === "danger" ? "var(--danger)" : "var(--fg)";
  return (
    <div className="card statcard">
      <div className="k">{k}</div>
      {loading
        ? <div className="v"><Skeleton h={20} w={56} radius={5} style={{ margin: "3px 0" }} /></div>
        : <div className="v" style={{ color }}>{v}</div>}
      <div className="sub">
        {loading ? <Skeleton h={9} w={72} radius={4} /> : (<>
          {delta && <span className={`delta ${delta.dir}`}>{delta.dir === "up" ? "▲" : delta.dir === "down" ? "▼" : "■"} {delta.text}</span>}
          {sub}
        </>)}
      </div>
    </div>
  );
}

export function CardHead({ title, hint, right }: { title: string; hint?: ReactNode; right?: ReactNode }) {
  return (
    <div style={{ display: "flex", alignItems: "baseline", gap: 10, marginBottom: 12 }}>
      <h3 style={{ margin: 0 }}>{title}</h3>
      {hint && <span className="hint">{hint}</span>}
      <div style={{ flex: 1 }} />
      {right}
    </div>
  );
}

/** Time-range segmented control. */
export function RangeToggle({ value, onChange, options = ["7d", "14d", "30d"] }: {
  value: string;
  onChange: (v: string) => void;
  options?: string[];
}) {
  return (
    <div className="seg">
      {options.map(o => (
        <button key={o} className={o === value ? "on" : ""} onClick={() => onChange(o)}>{o}</button>
      ))}
    </div>
  );
}

/** A small agent/user avatar; `bot` renders a rounded-square agent glyph. */
export function Avatar({ login, size = 20, bot = false }: { login: string; size?: number; bot?: boolean }) {
  const color = bot ? "oklch(0.78 0.14 70)" : loginColor(login);
  return (
    <span title={login} className="mono" style={{
      width: size, height: size, borderRadius: bot ? size * 0.28 : "50%",
      background: color, color: "#1a120a",
      fontWeight: 700, fontSize: size * 0.46,
      display: "inline-flex", alignItems: "center", justifyContent: "center", flexShrink: 0,
    }}>
      {bot ? "◆" : (login.replace(/^@/, "")[0]?.toUpperCase() ?? "?")}
    </span>
  );
}

/** A lightweight hover-tooltip controller for the charts. Render `node` once
 *  near the page root; pass the handle to a chart's `tip` prop. */
export function useTip(): ChartTip & { node: ReactNode } {
  const [tip, setTip] = useState<{ x: number; y: number; content: ReactNode } | null>(null);
  const show = useCallback((x: number, y: number, content: ReactNode) => setTip({ x, y, content }), []);
  const hide = useCallback(() => setTip(null), []);
  const tipStyle: CSSProperties = tip
    ? { left: tip.x, top: tip.y, transform: "translate(-50%,-120%)" }
    : {};
  const node = tip ? <div className="chart-tip" style={tipStyle}>{tip.content}</div> : null;
  return { show, hide, node };
}

// Shared analytics chart primitives (#399), ported from
// design/fleet-github-skills/js/charts.jsx. On-brand viewBox-based SVG charts
// tuned to the token system, with optional hover tooltips (see useTip). Used by
// the Fleet and (later) Repo Pulse analytics pages.
import type { ReactNode } from "react";

/** Hover-tooltip controller handle (see {@link useTip}). */
export interface ChartTip {
  show: (x: number, y: number, content: ReactNode) => void;
  hide: () => void;
}

// ── multi-series line / area ────────────────────────────────────────────────
export interface LineSeries {
  name: string;
  color: string;
  data: number[];
  width?: number;
  dash?: string;
  dots?: boolean;
  fill?: boolean;
  dotR?: number;
}
interface LineAreaProps {
  series: LineSeries[];
  labels: string[];
  height?: number;
  yMax?: number;
  area?: boolean;
  fmtY?: (v: number) => ReactNode;
  tip?: ChartTip;
}
export function LineArea({ series, labels, height = 150, yMax, area = true, fmtY = (v) => v, tip }: LineAreaProps) {
  const W = 720, H = height, PAD = { l: 34, r: 14, t: 12, b: 22 };
  const iw = W - PAD.l - PAD.r, ih = H - PAD.t - PAD.b;
  const n = labels.length;
  const max = yMax ?? Math.max(1, ...series.flatMap(s => s.data));
  const x = (i: number) => PAD.l + (n <= 1 ? iw / 2 : (i / (n - 1)) * iw);
  const y = (v: number) => PAD.t + (1 - v / max) * ih;
  const yTicks = [0, 0.25, 0.5, 0.75, 1].map(t => Math.round(max * t));
  return (
    <svg viewBox={`0 0 ${W} ${H}`} style={{ width: "100%", display: "block" }} onMouseLeave={() => tip?.hide()}>
      {yTicks.map((v, i) => (
        <g key={i}>
          <line x1={PAD.l} y1={y(v)} x2={W - PAD.r} y2={y(v)} stroke="var(--border-soft)" strokeDasharray="2 3" />
          <text x={PAD.l - 5} y={y(v) + 3} textAnchor="end" fontFamily="var(--mono)" fontSize="9" fill="var(--fg-dim)">{fmtY(v)}</text>
        </g>
      ))}
      {labels.map((l, i) => i % Math.ceil(n / 8 || 1) === 0 && (
        <text key={i} x={x(i)} y={H - PAD.b + 13} textAnchor="middle" fontFamily="var(--mono)" fontSize="8.5" fill="var(--fg-dim)">{l}</text>
      ))}
      {series.map((s, si) => {
        const line = s.data.map((v, i) => `${i === 0 ? "M" : "L"} ${x(i)} ${y(v)}`).join(" ");
        const fillPath = `${line} L ${x(n - 1)} ${y(0)} L ${x(0)} ${y(0)} Z`;
        const show = (e: React.MouseEvent, i: number) =>
          tip?.show(e.clientX, e.clientY, <span><b style={{ color: s.color }}>{s.name}</b> · {labels[i]} · {fmtY(s.data[i])}</span>);
        return (
          <g key={si}>
            {area && s.fill !== false && <path d={fillPath} fill={s.color} opacity="0.12" />}
            <path d={line} fill="none" stroke={s.color} strokeWidth={s.width ?? 2} strokeDasharray={s.dash ?? "0"} strokeLinejoin="round" strokeLinecap="round" />
            {s.dots !== false && s.data.map((v, i) => (
              <circle key={i} cx={x(i)} cy={y(v)} r={s.dotR ?? 2.4} fill={s.color}
                style={{ cursor: tip ? "pointer" : "default" }}
                onMouseEnter={(e) => show(e, i)} onMouseMove={(e) => show(e, i)} />
            ))}
          </g>
        );
      })}
    </svg>
  );
}

// ── grouped / stacked bars ──────────────────────────────────────────────────
export interface BarGroup { name: string; color: string; data: number[] }
interface BarsProps {
  groups: BarGroup[];
  labels: string[];
  height?: number;
  stacked?: boolean;
  fmtY?: (v: number) => ReactNode;
  tip?: ChartTip;
}
export function Bars({ groups, labels, height = 130, stacked = false, fmtY = (v) => v, tip }: BarsProps) {
  const W = 720, H = height, PAD = { l: 30, r: 12, t: 10, b: 22 };
  const iw = W - PAD.l - PAD.r, ih = H - PAD.t - PAD.b;
  const n = labels.length;
  const seriesCount = groups.length;
  const max = stacked
    ? Math.max(1, ...labels.map((_, i) => groups.reduce((s, g) => s + g.data[i], 0)))
    : Math.max(1, ...groups.flatMap(g => g.data));
  const slot = iw / n;
  const y = (v: number) => PAD.t + (1 - v / max) * ih;
  const bw = stacked ? Math.min(26, slot * 0.5) : Math.min(13, (slot * 0.7) / seriesCount);
  return (
    <svg viewBox={`0 0 ${W} ${H}`} style={{ width: "100%", display: "block" }} onMouseLeave={() => tip?.hide()}>
      {[0, 0.5, 1].map((t, i) => {
        const v = Math.round(max * t);
        return <g key={i}><line x1={PAD.l} y1={y(v)} x2={W - PAD.r} y2={y(v)} stroke="var(--border-soft)" strokeDasharray="2 3" />
          <text x={PAD.l - 4} y={y(v) + 3} textAnchor="end" fontFamily="var(--mono)" fontSize="9" fill="var(--fg-dim)">{fmtY(v)}</text></g>;
      })}
      {labels.map((lab, i) => {
        const cx = PAD.l + slot * i + slot / 2;
        return (
          <g key={i}>
            {groups.map((g, gi) => {
              const v = g.data[i];
              const h = (v / max) * ih;
              // Stacked offset = sum of preceding groups at this label (no mutation).
              const below = groups.slice(0, gi).reduce((a, gg) => a + gg.data[i], 0);
              let bx: number, by: number;
              if (stacked) { bx = cx - bw / 2; by = y(below + v); }
              else { bx = cx - (bw * seriesCount + 2 * (seriesCount - 1)) / 2 + gi * (bw + 2); by = y(v); }
              return <rect key={gi} x={bx} y={by} width={bw} height={Math.max(0, h)} rx="1.5" fill={g.color}
                style={{ cursor: tip ? "pointer" : "default" }}
                onMouseMove={(e) => tip?.show(e.clientX, e.clientY, <span><b style={{ color: g.color }}>{g.name}</b> · {lab} · {fmtY(v)}</span>)} />;
            })}
            <text x={cx} y={H - PAD.b + 13} textAnchor="middle" fontFamily="var(--mono)" fontSize="8.5" fill="var(--fg-dim)">{lab}</text>
          </g>
        );
      })}
    </svg>
  );
}

// ── donut / gauge ───────────────────────────────────────────────────────────
export interface DonutSlice { name: string; value: number; color: string }
interface DonutProps { slices: DonutSlice[]; size?: number; thickness?: number; center?: { value: ReactNode; label: string } }
export function Donut({ slices, size = 132, thickness = 16, center }: DonutProps) {
  const r = (size - thickness) / 2, cx = size / 2, cy = size / 2;
  const C = 2 * Math.PI * r;
  const total = slices.reduce((s, x) => s + x.value, 0) || 1;
  return (
    <svg width={size} height={size} viewBox={`0 0 ${size} ${size}`}>
      <circle cx={cx} cy={cy} r={r} fill="none" stroke="var(--bg-elev2)" strokeWidth={thickness} />
      {slices.map((s, i) => {
        const frac = s.value / total;
        const dash = frac * C;
        // Cumulative offset of preceding slices (no render-time mutation).
        const before = slices.slice(0, i).reduce((a, x) => a + x.value, 0) / total;
        return <circle key={i} cx={cx} cy={cy} r={r} fill="none" stroke={s.color}
          strokeWidth={thickness} strokeDasharray={`${dash} ${C - dash}`}
          strokeDashoffset={-before * C} transform={`rotate(-90 ${cx} ${cy})`}><title>{s.name}: {s.value}</title></circle>;
      })}
      {center && <>
        <text x={cx} y={cy - 2} textAnchor="middle" fontFamily="var(--mono)" fontSize="20" fontWeight="700" fill="var(--fg)">{center.value}</text>
        <text x={cx} y={cy + 14} textAnchor="middle" fontFamily="var(--mono)" fontSize="9" fill="var(--fg-dim)">{center.label}</text>
      </>}
    </svg>
  );
}

// ── horizontal bars (ranked) ─────────────────────────────────────────────────
export interface HBarRow {
  label: string;
  value: number;
  color?: string;
  strong?: boolean;
  icon?: ReactNode;
  tag?: ReactNode;
}
interface HBarsProps { rows: HBarRow[]; fmtV?: (v: number) => ReactNode; max?: number }
export function HBars({ rows, fmtV = (v) => v, max: maxOverride }: HBarsProps) {
  const max = maxOverride ?? Math.max(1, ...rows.map(r => r.value));
  return (
    <div style={{ display: "flex", flexDirection: "column", gap: 7 }}>
      {rows.map((r, i) => (
        <div key={i} className="hrow" style={{ display: "grid", gridTemplateColumns: "minmax(0,1fr) 46px", gap: 10, alignItems: "center", padding: "1px 2px", borderRadius: 4 }}>
          <div style={{ minWidth: 0 }}>
            <div className="mono" style={{ display: "flex", alignItems: "center", gap: 7, marginBottom: 3, fontSize: 10.5, color: "var(--fg-muted)" }}>
              {r.icon}
              <span style={{ whiteSpace: "nowrap", overflow: "hidden", textOverflow: "ellipsis", color: r.strong ? "var(--fg)" : undefined }}>{r.label}</span>
              {r.tag}
            </div>
            <div className="meter" style={{ height: 6 }}>
              <i style={{ width: `${(r.value / max) * 100}%`, background: r.color ?? "var(--accent)" }} />
            </div>
          </div>
          <div className="mono" style={{ textAlign: "right", fontSize: 11, color: "var(--fg)" }}>{fmtV(r.value)}</div>
        </div>
      ))}
    </div>
  );
}

// ── swimlane / activity timeline ─────────────────────────────────────────────
export interface SwimLane { name: string; color?: string }
export interface SwimEvent { lane: number; t0: number; t1?: number; color: string; label: string; r?: number }
export interface SwimMark { t: number; label: string }
interface SwimlaneProps { lanes: SwimLane[]; events: SwimEvent[]; height?: number; tip?: ChartTip; marks?: SwimMark[] }
export function Swimlane({ lanes, events, height = 26, tip, marks = [] }: SwimlaneProps) {
  const W = 720, laneH = height, top = 16, left = 96, right = 14;
  const iw = W - left - right;
  const H = top + lanes.length * laneH + 6;
  const xt = (t: number) => left + t * iw;
  return (
    <svg viewBox={`0 0 ${W} ${H}`} style={{ width: "100%", display: "block" }} onMouseLeave={() => tip?.hide()}>
      {marks.map((m, i) => (
        <g key={`mk${i}`}>
          <line x1={xt(m.t)} y1={top - 4} x2={xt(m.t)} y2={H - 4} stroke="var(--border-soft)" strokeDasharray="2 4" />
          <text x={xt(m.t)} y={top - 6} textAnchor="middle" fontFamily="var(--mono)" fontSize="8" fill="var(--fg-dim)">{m.label}</text>
        </g>
      ))}
      {lanes.map((ln, li) => {
        const cy = top + li * laneH + laneH / 2;
        return (
          <g key={li}>
            <text x={left - 8} y={cy + 3} textAnchor="end" fontFamily="var(--mono)" fontSize="9.5" fill={ln.color ?? "var(--fg-muted)"}>{ln.name}</text>
            <line x1={left} y1={cy} x2={W - right} y2={cy} stroke="var(--border-soft)" strokeWidth="1" />
          </g>
        );
      })}
      {events.map((e, i) => {
        const cy = top + e.lane * laneH + laneH / 2;
        if (e.t1 != null) {
          const x0 = xt(e.t0), x1 = xt(e.t1);
          return <rect key={i} x={x0} y={cy - 4} width={Math.max(3, x1 - x0)} height={8} rx="3" fill={e.color} opacity="0.85"
            style={{ cursor: tip ? "pointer" : "default" }}
            onMouseMove={(ev) => tip?.show(ev.clientX, ev.clientY, <span>{e.label}</span>)} />;
        }
        return <circle key={i} cx={xt(e.t0)} cy={cy} r={e.r ?? 4} fill={e.color} stroke="var(--bg-panel)" strokeWidth="1.5"
          style={{ cursor: tip ? "pointer" : "default" }}
          onMouseMove={(ev) => tip?.show(ev.clientX, ev.clientY, <span>{e.label}</span>)} />;
      })}
    </svg>
  );
}

// ── inline sparkline ─────────────────────────────────────────────────────────
interface SparkProps { data: number[]; color: string; w?: number; h?: number; fill?: boolean; dot?: boolean }
export function Spark({ data, color, w = 70, h = 20, fill = true, dot = true }: SparkProps) {
  if (data.length < 2) return null;
  const max = Math.max(1, ...data), min = Math.min(...data);
  const span = max - min || 1;
  const x = (i: number) => (i / (data.length - 1)) * w;
  const y = (v: number) => h - 2 - ((v - min) / span) * (h - 4);
  const line = data.map((v, i) => `${i === 0 ? "M" : "L"} ${x(i).toFixed(1)} ${y(v).toFixed(1)}`).join(" ");
  return (
    <svg width={w} height={h} viewBox={`0 0 ${w} ${h}`} style={{ display: "block" }}>
      {fill && <path d={`${line} L ${w} ${h} L 0 ${h} Z`} fill={color} opacity="0.13" />}
      <path d={line} fill="none" stroke={color} strokeWidth="1.6" strokeLinejoin="round" strokeLinecap="round" />
      {dot && <circle cx={x(data.length - 1)} cy={y(data[data.length - 1])} r="2" fill={color} />}
    </svg>
  );
}

// ── stacked daily bars (over-time) card ───────────────────────────────────────
// A panel-wrapped, two-series stacked bar chart over a fixed run of days — the shared
// "Calls/Fires over time" card on the MCP + Hook analytics tabs (#1740). `lower` stacks
// at the baseline, `upper` on top of it. Day labels show every 3rd bucket.
export interface StackedDay { day: string; upper: number; lower: number }
export function StackedDayBars({
  data, title, subtitle, upperLabel, lowerLabel,
  upperColor = "var(--accent)", lowerColor = "var(--danger)",
}: {
  data: StackedDay[];
  title: string;
  subtitle: string;
  upperLabel: string;
  lowerLabel: string;
  upperColor?: string;
  lowerColor?: string;
}) {
  const W = 600, H = 160, x0 = 30, baseY = 140, topY = 12;
  const n = data.length || 1;
  const maxTotal = Math.max(1, ...data.map((d) => d.lower + d.upper));
  const bw = (W - x0 - 10) / n;
  const scaleY = (v: number) => (v / maxTotal) * (baseY - topY);
  const gridVals = [0, Math.ceil(maxTotal / 2), maxTotal];
  return (
    <div style={{ background: "var(--bg-panel)", border: "1px solid var(--border-soft)", borderRadius: 8, padding: "14px 16px", marginBottom: 10 }}>
      <div style={{ display: "flex", alignItems: "baseline", gap: 10, marginBottom: 10 }}>
        <h3 className="mono" style={{ margin: 0, fontSize: 11, color: "var(--fg)", fontWeight: 600 }}>{title}</h3>
        <span style={{ fontSize: 10.5, color: "var(--fg-dim)" }}>{subtitle}</span>
        <div style={{ flex: 1 }} />
        <span className="mono" style={{ display: "inline-flex", alignItems: "center", gap: 5, fontSize: 10, color: "var(--fg-muted)" }}><span style={{ width: 9, height: 9, borderRadius: 2, background: upperColor }} />{upperLabel}</span>
        <span className="mono" style={{ display: "inline-flex", alignItems: "center", gap: 5, fontSize: 10, color: "var(--fg-muted)" }}><span style={{ width: 9, height: 9, borderRadius: 2, background: lowerColor }} />{lowerLabel}</span>
      </div>
      <svg viewBox={`0 0 ${W} ${H}`} className="mono" style={{ width: "100%", height: "auto", display: "block" }}>
        {gridVals.map((v, i) => {
          const y = baseY - scaleY(v);
          return (
            <g key={i}>
              <line x1={x0} y1={y} x2={W - 8} y2={y} stroke="var(--border-soft)" strokeWidth={1} />
              <text x={x0 - 6} y={y + 3} textAnchor="end" fill="var(--fg-dim)" fontSize={9}>{v}</text>
            </g>
          );
        })}
        {data.map((d, i) => {
          const x = x0 + 4 + i * bw;
          const w = bw - 5;
          const hLower = scaleY(d.lower);
          const hUpper = scaleY(d.upper);
          const yLower = baseY - hLower;
          const yUpper = yLower - hUpper;
          const showLabel = i % 3 === 0;
          return (
            <g key={i}>
              {hLower > 0 && <rect x={x} y={yLower} width={w} height={hLower} rx={2} fill={lowerColor} />}
              {hUpper > 0 && <rect x={x} y={yUpper} width={w} height={hUpper} rx={2} fill={upperColor} />}
              {showLabel && <text x={x + w / 2} y={152} textAnchor="middle" fill="var(--fg-dim)" fontSize={8.5}>{d.day.slice(5)}</text>}
            </g>
          );
        })}
      </svg>
    </div>
  );
}

// ── legend ──────────────────────────────────────────────────────────────────
export interface LegendItem { color: string; label: string; value?: ReactNode }
export function Legend({ items, style }: { items: LegendItem[]; style?: React.CSSProperties }) {
  return (
    <div className="mono" style={{ display: "flex", gap: 14, flexWrap: "wrap", fontSize: 10, color: "var(--fg-muted)", ...style }}>
      {items.map((it, i) => (
        <span key={i} style={{ display: "inline-flex", alignItems: "center", gap: 6 }}>
          <span style={{ width: 9, height: 9, borderRadius: 2, background: it.color, display: "inline-block" }} />
          {it.label}{it.value != null && <b style={{ color: "var(--fg)" }}>{it.value}</b>}
        </span>
      ))}
    </div>
  );
}

// Shared analytics chart primitives (#399), ported from
// design/fleet-github-skills/js/charts.jsx. On-brand viewBox-based SVG charts
// tuned to the token system, with optional hover tooltips (see useTip). Used by
// the Fleet and (later) Repo Pulse analytics pages.
import type { ReactNode } from "react";

/** Hover-tooltip controller handle (see {@link useTip}). */
export interface ChartTip {
  show: (x: number, y: number, content: ReactNode) => void;
  hide: () => void;
}

// ── multi-series line / area ────────────────────────────────────────────────
export interface LineSeries {
  name: string;
  color: string;
  data: number[];
  width?: number;
  dash?: string;
  dots?: boolean;
  fill?: boolean;
  dotR?: number;
}
interface LineAreaProps {
  series: LineSeries[];
  labels: string[];
  height?: number;
  yMax?: number;
  area?: boolean;
  fmtY?: (v: number) => ReactNode;
  tip?: ChartTip;
}
export function LineArea({ series, labels, height = 150, yMax, area = true, fmtY = (v) => v, tip }: LineAreaProps) {
  const W = 720, H = height, PAD = { l: 34, r: 14, t: 12, b: 22 };
  const iw = W - PAD.l - PAD.r, ih = H - PAD.t - PAD.b;
  const n = labels.length;
  const max = yMax ?? Math.max(1, ...series.flatMap(s => s.data));
  const x = (i: number) => PAD.l + (n <= 1 ? iw / 2 : (i / (n - 1)) * iw);
  const y = (v: number) => PAD.t + (1 - v / max) * ih;
  const yTicks = [0, 0.25, 0.5, 0.75, 1].map(t => Math.round(max * t));
  return (
    <svg viewBox={`0 0 ${W} ${H}`} style={{ width: "100%", display: "block" }} onMouseLeave={() => tip?.hide()}>
      {yTicks.map((v, i) => (
        <g key={i}>
          <line x1={PAD.l} y1={y(v)} x2={W - PAD.r} y2={y(v)} stroke="var(--border-soft)" strokeDasharray="2 3" />
          <text x={PAD.l - 5} y={y(v) + 3} textAnchor="end" fontFamily="var(--mono)" fontSize="9" fill="var(--fg-dim)">{fmtY(v)}</text>
        </g>
      ))}
      {labels.map((l, i) => i % Math.ceil(n / 8 || 1) === 0 && (
        <text key={i} x={x(i)} y={H - PAD.b + 13} textAnchor="middle" fontFamily="var(--mono)" fontSize="8.5" fill="var(--fg-dim)">{l}</text>
      ))}
      {series.map((s, si) => {
        const line = s.data.map((v, i) => `${i === 0 ? "M" : "L"} ${x(i)} ${y(v)}`).join(" ");
        const fillPath = `${line} L ${x(n - 1)} ${y(0)} L ${x(0)} ${y(0)} Z`;
        const show = (e: React.MouseEvent, i: number) =>
          tip?.show(e.clientX, e.clientY, <span><b style={{ color: s.color }}>{s.name}</b> · {labels[i]} · {fmtY(s.data[i])}</span>);
        return (
          <g key={si}>
            {area && s.fill !== false && <path d={fillPath} fill={s.color} opacity="0.12" />}
            <path d={line} fill="none" stroke={s.color} strokeWidth={s.width ?? 2} strokeDasharray={s.dash ?? "0"} strokeLinejoin="round" strokeLinecap="round" />
            {s.dots !== false && s.data.map((v, i) => (
              <circle key={i} cx={x(i)} cy={y(v)} r={s.dotR ?? 2.4} fill={s.color}
                style={{ cursor: tip ? "pointer" : "default" }}
                onMouseEnter={(e) => show(e, i)} onMouseMove={(e) => show(e, i)} />
            ))}
          </g>
        );
      })}
    </svg>
  );
}

// ── grouped / stacked bars ──────────────────────────────────────────────────
export interface BarGroup { name: string; color: string; data: number[] }
interface BarsProps {
  groups: BarGroup[];
  labels: string[];
  height?: number;
  stacked?: boolean;
  fmtY?: (v: number) => ReactNode;
  tip?: ChartTip;
}
export function Bars({ groups, labels, height = 130, stacked = false, fmtY = (v) => v, tip }: BarsProps) {
  const W = 720, H = height, PAD = { l: 30, r: 12, t: 10, b: 22 };
  const iw = W - PAD.l - PAD.r, ih = H - PAD.t - PAD.b;
  const n = labels.length;
  const seriesCount = groups.length;
  const max = stacked
    ? Math.max(1, ...labels.map((_, i) => groups.reduce((s, g) => s + g.data[i], 0)))
    : Math.max(1, ...groups.flatMap(g => g.data));
  const slot = iw / n;
  const y = (v: number) => PAD.t + (1 - v / max) * ih;
  const bw = stacked ? Math.min(26, slot * 0.5) : Math.min(13, (slot * 0.7) / seriesCount);
  return (
    <svg viewBox={`0 0 ${W} ${H}`} style={{ width: "100%", display: "block" }} onMouseLeave={() => tip?.hide()}>
      {[0, 0.5, 1].map((t, i) => {
        const v = Math.round(max * t);
        return <g key={i}><line x1={PAD.l} y1={y(v)} x2={W - PAD.r} y2={y(v)} stroke="var(--border-soft)" strokeDasharray="2 3" />
          <text x={PAD.l - 4} y={y(v) + 3} textAnchor="end" fontFamily="var(--mono)" fontSize="9" fill="var(--fg-dim)">{fmtY(v)}</text></g>;
      })}
      {labels.map((lab, i) => {
        const cx = PAD.l + slot * i + slot / 2;
        return (
          <g key={i}>
            {groups.map((g, gi) => {
              const v = g.data[i];
              const h = (v / max) * ih;
              // Stacked offset = sum of preceding groups at this label (no mutation).
              const below = groups.slice(0, gi).reduce((a, gg) => a + gg.data[i], 0);
              let bx: number, by: number;
              if (stacked) { bx = cx - bw / 2; by = y(below + v); }
              else { bx = cx - (bw * seriesCount + 2 * (seriesCount - 1)) / 2 + gi * (bw + 2); by = y(v); }
              return <rect key={gi} x={bx} y={by} width={bw} height={Math.max(0, h)} rx="1.5" fill={g.color}
                style={{ cursor: tip ? "pointer" : "default" }}
                onMouseMove={(e) => tip?.show(e.clientX, e.clientY, <span><b style={{ color: g.color }}>{g.name}</b> · {lab} · {fmtY(v)}</span>)} />;
            })}
            <text x={cx} y={H - PAD.b + 13} textAnchor="middle" fontFamily="var(--mono)" fontSize="8.5" fill="var(--fg-dim)">{lab}</text>
          </g>
        );
      })}
    </svg>
  );
}

// ── donut / gauge ───────────────────────────────────────────────────────────
export interface DonutSlice { name: string; value: number; color: string }
interface DonutProps { slices: DonutSlice[]; size?: number; thickness?: number; center?: { value: ReactNode; label: string } }
export function Donut({ slices, size = 132, thickness = 16, center }: DonutProps) {
  const r = (size - thickness) / 2, cx = size / 2, cy = size / 2;
  const C = 2 * Math.PI * r;
  const total = slices.reduce((s, x) => s + x.value, 0) || 1;
  return (
    <svg width={size} height={size} viewBox={`0 0 ${size} ${size}`}>
      <circle cx={cx} cy={cy} r={r} fill="none" stroke="var(--bg-elev2)" strokeWidth={thickness} />
      {slices.map((s, i) => {
        const frac = s.value / total;
        const dash = frac * C;
        // Cumulative offset of preceding slices (no render-time mutation).
        const before = slices.slice(0, i).reduce((a, x) => a + x.value, 0) / total;
        return <circle key={i} cx={cx} cy={cy} r={r} fill="none" stroke={s.color}
          strokeWidth={thickness} strokeDasharray={`${dash} ${C - dash}`}
          strokeDashoffset={-before * C} transform={`rotate(-90 ${cx} ${cy})`}><title>{s.name}: {s.value}</title></circle>;
      })}
      {center && <>
        <text x={cx} y={cy - 2} textAnchor="middle" fontFamily="var(--mono)" fontSize="20" fontWeight="700" fill="var(--fg)">{center.value}</text>
        <text x={cx} y={cy + 14} textAnchor="middle" fontFamily="var(--mono)" fontSize="9" fill="var(--fg-dim)">{center.label}</text>
      </>}
    </svg>
  );
}

// ── horizontal bars (ranked) ─────────────────────────────────────────────────
export interface HBarRow {
  label: string;
  value: number;
  color?: string;
  strong?: boolean;
  icon?: ReactNode;
  tag?: ReactNode;
}
interface HBarsProps { rows: HBarRow[]; fmtV?: (v: number) => ReactNode; max?: number }
export function HBars({ rows, fmtV = (v) => v, max: maxOverride }: HBarsProps) {
  const max = maxOverride ?? Math.max(1, ...rows.map(r => r.value));
  return (
    <div style={{ display: "flex", flexDirection: "column", gap: 7 }}>
      {rows.map((r, i) => (
        <div key={i} className="hrow" style={{ display: "grid", gridTemplateColumns: "minmax(0,1fr) 46px", gap: 10, alignItems: "center", padding: "1px 2px", borderRadius: 4 }}>
          <div style={{ minWidth: 0 }}>
            <div className="mono" style={{ display: "flex", alignItems: "center", gap: 7, marginBottom: 3, fontSize: 10.5, color: "var(--fg-muted)" }}>
              {r.icon}
              <span style={{ whiteSpace: "nowrap", overflow: "hidden", textOverflow: "ellipsis", color: r.strong ? "var(--fg)" : undefined }}>{r.label}</span>
              {r.tag}
            </div>
            <div className="meter" style={{ height: 6 }}>
              <i style={{ width: `${(r.value / max) * 100}%`, background: r.color ?? "var(--accent)" }} />
            </div>
          </div>
          <div className="mono" style={{ textAlign: "right", fontSize: 11, color: "var(--fg)" }}>{fmtV(r.value)}</div>
        </div>
      ))}
    </div>
