// ── inline sparkline ─────────────────────────────────────────────────────────
interface SparkProps { data: number[]; color: string; w?: number; h?: number; fill?: boolean; dot?: boolean }
export function Spark({ data, color, w = 70, h = 20, fill = true, dot = true }: SparkProps) {
  if (data.length < 2) return null;
  const max = Math.max(1, ...data), min = Math.min(...data);
  const span = max - min || 1;
  const x = (i: number) => (i / (data.length - 1)) * w;
  const y = (v: number) => h - 2 - ((v - min) / span) * (h - 4);
  const line = data.map((v, i) => `${i === 0 ? "M" : "L"} ${x(i).toFixed(1)} ${y(v).toFixed(1)}`).join(" ");
  return (
    <svg width={w} height={h} viewBox={`0 0 ${w} ${h}`} style={{ display: "block" }}>
      {fill && <path d={`${line} L ${w} ${h} L 0 ${h} Z`} fill={color} opacity="0.13" />}
      <path d={line} fill="none" stroke={color} strokeWidth="1.6" strokeLinejoin="round" strokeLinecap="round" />
      {dot && <circle cx={x(data.length - 1)} cy={y(data[data.length - 1])} r="2" fill={color} />}
    </svg>
  );
}

// ── stacked daily bars (over-time) card ───────────────────────────────────────
// A panel-wrapped, two-series stacked bar chart over a fixed run of days — the shared
// "Calls/Fires over time" card on the MCP + Hook analytics tabs (#1740). `lower` stacks
// at the baseline, `upper` on top of it. Day labels show every 3rd bucket.
export interface StackedDay { day: string; upper: number; lower: number }
export function StackedDayBars({
  data, title, subtitle, upperLabel, lowerLabel,
  upperColor = "var(--accent)", lowerColor = "var(--danger)",
}: {
  data: StackedDay[];
  title: string;
  subtitle: string;
  upperLabel: string;
  lowerLabel: string;
  upperColor?: string;
  lowerColor?: string;
}) {
  const W = 600, H = 160, x0 = 30, baseY = 140, topY = 12;
  const n = data.length || 1;
  const maxTotal = Math.max(1, ...data.map((d) => d.lower + d.upper));
  const bw = (W - x0 - 10) / n;
  const scaleY = (v: number) => (v / maxTotal) * (baseY - topY);
  const gridVals = [0, Math.ceil(maxTotal / 2), maxTotal];
  return (
    <div style={{ background: "var(--bg-panel)", border: "1px solid var(--border-soft)", borderRadius: 8, padding: "14px 16px", marginBottom: 10 }}>
      <div style={{ display: "flex", alignItems: "baseline", gap: 10, marginBottom: 10 }}>
        <h3 className="mono" style={{ margin: 0, fontSize: 11, color: "var(--fg)", fontWeight: 600 }}>{title}</h3>
        <span style={{ fontSize: 10.5, color: "var(--fg-dim)" }}>{subtitle}</span>
        <div style={{ flex: 1 }} />
        <span className="mono" style={{ display: "inline-flex", alignItems: "center", gap: 5, fontSize: 10, color: "var(--fg-muted)" }}><span style={{ width: 9, height: 9, borderRadius: 2, background: upperColor }} />{upperLabel}</span>
        <span className="mono" style={{ display: "inline-flex", alignItems: "center", gap: 5, fontSize: 10, color: "var(--fg-muted)" }}><span style={{ width: 9, height: 9, borderRadius: 2, background: lowerColor }} />{lowerLabel}</span>
      </div>
      <svg viewBox={`0 0 ${W} ${H}`} className="mono" style={{ width: "100%", height: "auto", display: "block" }}>
        {gridVals.map((v, i) => {
          const y = baseY - scaleY(v);
          return (
            <g key={i}>
              <line x1={x0} y1={y} x2={W - 8} y2={y} stroke="var(--border-soft)" strokeWidth={1} />
              <text x={x0 - 6} y={y + 3} textAnchor="end" fill="var(--fg-dim)" fontSize={9}>{v}</text>
            </g>
          );
        })}
        {data.map((d, i) => {
          const x = x0 + 4 + i * bw;
          const w = bw - 5;
          const hLower = scaleY(d.lower);
          const hUpper = scaleY(d.upper);
          const yLower = baseY - hLower;
          const yUpper = yLower - hUpper;
          const showLabel = i % 3 === 0;
          return (
            <g key={i}>
              {hLower > 0 && <rect x={x} y={yLower} width={w} height={hLower} rx={2} fill={lowerColor} />}
              {hUpper > 0 && <rect x={x} y={yUpper} width={w} height={hUpper} rx={2} fill={upperColor} />}
              {showLabel && <text x={x + w / 2} y={152} textAnchor="middle" fill="var(--fg-dim)" fontSize={8.5}>{d.day.slice(5)}</text>}
            </g>
          );
        })}
      </svg>
    </div>
  );
}

// ── legend ──────────────────────────────────────────────────────────────────
export interface LegendItem { color: string; label: string; value?: ReactNode }
export function Legend({ items, style }: { items: LegendItem[]; style?: React.CSSProperties }) {
  return (
    <div className="mono" style={{ display: "flex", gap: 14, flexWrap: "wrap", fontSize: 10, color: "var(--fg-muted)", ...style }}>
      {items.map((it, i) => (
        <span key={i} style={{ display: "inline-flex", alignItems: "center", gap: 6 }}>
          <span style={{ width: 9, height: 9, borderRadius: 2, background: it.color, display: "inline-block" }} />
          {it.label}{it.value != null && <b style={{ color: "var(--fg)" }}>{it.value}</b>}
        </span>
      ))}
    </div>
  );
}

import type { ReactNode, CSSProperties } from "react";
import "./banner.css";

export interface BannerProps {
  /** Colour tone. Default "neutral". */
  tone?: "neutral" | "info" | "success" | "warn" | "danger" | "accent";
  /** Full-width app/screen bar (square, border-bottom) vs the default inline rounded callout. */
  variant?: "inline" | "bar";
  /** A leading icon/element. */
  lead?: ReactNode;
  /** Shorthand for a tone-colored status dot as the lead. */
  dot?: boolean;
  /** Tone-colored text (the louder "status" look) instead of the default muted text. */
  loud?: boolean;
  /** Right-aligned content — a caption or action buttons. */
  right?: ReactNode;
  /** Renders a trailing dismiss ✕; invoked on click. */
  onDismiss?: () => void;
  /** ARIA role — e.g. "alert" / "status" for announced banners. */
  role?: string;
  children: ReactNode;
  className?: string;
  style?: CSSProperties;
}

/** Banner — the one status strip. A toned, bordered row with an optional lead (icon or `dot`),
 *  content, a `right` slot, and an optional `onDismiss` ✕. The default is an inline rounded callout;
 *  `variant="bar"` makes it a full-width top-of-app/screen banner. Replaces the per-feature inline
 *  callouts, the `Notice` status box (`dot`/`loud`/`right`), AND the hand-rolled app banners. */
export function Banner({
  tone = "neutral", variant = "inline", lead, dot, loud, right, onDismiss, role, children, className, style,
}: BannerProps) {
  const cls = `banner tone-${tone}`
    + (variant === "bar" ? " bar" : "")
    + (loud ? " loud" : "")
    + (className ? ` ${className}` : "");
  return (
    <div className={cls} role={role} style={style}>
      {dot && <span className="banner-dot" />}
      {lead}
      {children}
      {/* Actions grouped into one block pushed right by `margin-left:auto` — NOT a separate `flex:1`
          spacer, which would compete with a `flex:1` body for space and squeeze the text in a narrow
          card. As one unit it can also wrap to its own row (see `.app-banner-stack`). */}
      {(right != null || onDismiss) && (
        <span className="banner-actions">
          {right}
          {onDismiss && <button className="banner-x" aria-label="Dismiss" onClick={onDismiss}>✕</button>}
        </span>
      )}
    </div>
  );
}

// InlineError — the small mono danger callout (#2138). A static, bordered, danger-toned box that
// wraps a short error string in monospace. The pattern was pasted ~identically at every place that
// surfaced a failed action or query (the delete-project modal, the published-projects list, the
// board query banner), so it lives here once.
//
// This is deliberately its own primitive rather than a Banner tone: Banner is a status STRIP (louder
// tint, optional lead/dismiss/right slots, a flex row), whereas this is a plain read-only callout —
// danger-colored monospace text on the fixed 88%-transparent danger wash, no icon, no dismiss. The
// only per-site knobs are padding, corner radius, and the border tint (60% vs 70%), all exposed so
// each call site renders pixel-identical to the inline version it replaced. `style` passes through
// for the per-site margin.

import type { CSSProperties, ReactNode } from "react";
import { Box, type Radius } from "@/shared/ui/layout/Box";
import type { Space } from "@/shared/ui/layout/space";

export interface InlineErrorProps {
  /** The error message. */
  children: ReactNode;
  /** Inner padding — a rung/px or a [block, inline] pair. Default [8, 12]. */
  pad?: Space | [Space, Space];
  /** Corner radius — a rung (sm/md/lg → --r-*) or raw px. Default 4. */
  radius?: Radius;
  /** Border tint — the transparency % of --danger in the 1px border. Default 70 (some sites use 60). */
  borderFade?: number;
  className?: string;
  style?: CSSProperties;
}

/** InlineError — the shared mono danger callout: monospace, danger-colored text on a translucent
 *  danger wash with a matching hairline border. Renders its message children; nothing else. */
export function InlineError({
  children, pad = [8, 12], radius = 4, borderFade = 70, className, style,
}: InlineErrorProps) {
  return (
    <Box
      className={"mono" + (className ? ` ${className}` : "")}
      pad={pad}
      radius={radius}
      bg="color-mix(in oklch, var(--danger), transparent 88%)"
      border={`color-mix(in oklch, var(--danger), transparent ${borderFade}%)`}
      style={{ fontSize: 11, color: "var(--danger)", ...style }}
    >
      {children}
    </Box>
  );
}

import type { CSSProperties, ReactNode } from "react";

export interface EmptyStateProps {
  /** Glyph/char or node shown in the icon box above the title. Omit for no icon. */
  icon?: ReactNode;
  /** `solid` (default): elev background, accent glyph — the onboarding/"connect" look.
   *  `dashed`: dashed border, dim glyph — the "nothing here / no match" look. */
  iconVariant?: "solid" | "dashed";
  title: ReactNode;
  description?: ReactNode;
  /** Action button(s). Composed by the caller so per-site button semantics (disabled,
   *  danger tint, `btn primary`, full-width) stay intact rather than being re-modelled. */
  actions?: ReactNode;
  /** Extra content rendered below the actions (e.g. a "scopes requested" box). */
  extra?: ReactNode;
  /** `inline` (default): a centered column that fills its flex parent (in-page empty states).
   *  `card`: a bordered, shadowed 460px panel (the standalone onboarding/connect screens). */
  variant?: "inline" | "card";
  /** Content alignment. `center` (default) for the symmetric empty states; `left` for the
   *  richer GitHub-page connect card, which left-aligns its icon, copy, and CTA. */
  align?: "center" | "left";
  /** `md` (default) — the full page/section empty state. `sm` — a compact footprint (smaller icon,
   *  title, padding) for an EMPTY state sitting inside a card body (#2234). */
  size?: "sm" | "md";
  className?: string;
  style?: CSSProperties;
}

/** The shared "empty state + CTA" box: optional icon · title · description · action button(s) ·
 *  optional extra. Replaces the hand-rolled centered-stack that was copied across the connect
 *  screens, the skills no-match state, and the automations empty state (#1823). */
export function EmptyState({
  icon, iconVariant = "solid", title, description, actions, extra,
  variant = "inline", align = "center", size = "md", className, style,
}: EmptyStateProps) {
  const isCard = variant === "card";
  const left = align === "left";
  const sm = size === "sm";

  const iconBox = icon != null && (
    <div className="mono" style={{
      width: sm ? 38 : 54, height: sm ? 38 : 54, borderRadius: sm ? 11 : 14,
      margin: left ? `0 0 ${sm ? 12 : 18}px` : `0 auto ${sm ? 12 : 18}px`,
      display: "flex", alignItems: "center", justifyContent: "center",
      fontSize: sm ? 17 : 24,
      background: iconVariant === "solid" ? "var(--bg-elev)" : "transparent",
      border: `1px ${iconVariant === "dashed" ? "dashed" : "solid"} var(--border)`,
      color: iconVariant === "solid" ? "var(--accent)" : "var(--fg-dim)",
    }}>{icon}</div>
  );

  const body = (
    <>
      {iconBox}
      <h2 className="mono" style={{ margin: 0, fontSize: isCard ? 18 : sm ? 12.5 : 15, fontWeight: 600 }}>
        {title}
      </h2>
      {description != null && (
        <p style={{ margin: `${sm ? 6 : 8}px 0 0`, color: "var(--fg-muted)", fontSize: isCard ? 13 : sm ? 11 : 12.5, lineHeight: 1.55, maxWidth: left ? undefined : 400 }}>
          {description}
        </p>
      )}
      {actions != null && (
        <div style={{ display: "flex", gap: 8, justifyContent: left ? "flex-start" : "center", marginTop: 18, width: isCard ? "100%" : undefined }}>
          {actions}
        </div>
      )}
      {extra}
    </>
  );

  if (isCard) {
    return (
      <div className={className} style={{
        width: 460, padding: "36px 36px 32px",
        background: "var(--bg-panel)", border: "1px solid var(--border-soft)",
        borderRadius: 12, boxShadow: "0 18px 50px rgba(0,0,0,0.4)", textAlign: left ? "left" : "center",
        ...style,
      }}>
        {body}
      </div>
    );
  }
  return (
    <div className={className} style={{
      flex: 1, display: "flex", flexDirection: "column",
      alignItems: left ? "flex-start" : "center",
      justifyContent: "center", textAlign: left ? "left" : "center", padding: sm ? "22px 16px" : "40px 20px", ...style,
    }}>
      {body}
    </div>
  );
}

// StatusDot (#1777) — one small colored status dot, replacing the hand-prepended `●` glyph and the
// ad-hoc inline circle <span>s scattered across the app. Defaults to `currentColor` so dropping it
// into a `.tag`/`.tag.green`/etc. inherits that element's color exactly (the `●` glyph did the same),
// or pass a semantic `state` to use the shared `--state-*` tokens, or an explicit `color`.
import type { CSSProperties } from "react";

/** Canonical activity states → their design token (tokens.css `--state-*`). */
export type DotState = "run" | "wait" | "idle" | "stopped";

const STATE_COLOR: Record<DotState, string> = {
  run: "var(--state-run)",
  wait: "var(--state-wait)",
  idle: "var(--state-idle)",
  stopped: "var(--state-stopped)",
};

export interface StatusDotProps {
  /** Semantic state → its `--state-*` token. Ignored when `color` is set. */
  state?: DotState;
  /** Explicit color. Defaults to `currentColor` (inherits the surrounding tag/text color). */
  color?: string;
  /** Diameter in px (default 6). */
  size?: number;
  /** Pulse animation — a live "running" indicator. */
  pulse?: boolean;
  /** Native tooltip; when set, the dot is exposed to AT, otherwise it's `aria-hidden`. */
  title?: string;
  style?: CSSProperties;
}

export function StatusDot({ state, color, size = 6, pulse = false, title, style }: StatusDotProps) {
  const background = color ?? (state ? STATE_COLOR[state] : "currentColor");
  return (
    <span
      {...(title ? { title } : { "aria-hidden": true })}
      style={{
        display: "inline-block",
        width: size,
        height: size,
        flex: `0 0 ${size}px`,
        borderRadius: "50%",
        background,
        ...(pulse ? { animation: "pulse 1.4s ease-in-out infinite" } : {}),
        ...style,
      }}
    />
  );
}

// Skeleton (#2234) — the shared loading placeholder. A shimmering block that keeps a page's LAYOUT
// present while data loads, instead of a blank screen: a card body renders skeletons shaped like the
// content it's waiting for. Pairs with EmptyState (the no-data view) — a card body is one of three:
// loading skeleton · compact empty state · content.
//
// Built on the existing layout primitive (Box) + the `shimmer` style atom (./shimmer), promoted from the
// blueprint-import loading rows (#2128), so the whole app shares ONE skeleton look (keyframe
// `skeleton-shimmer`, tokens.css). Use the component, or spread `shimmer` onto any Box directly.
import type { CSSProperties } from "react";
import { Box } from "@/shared/ui/layout/Box";
import { shimmer } from "./shimmer";

export interface SkeletonProps {
  /** Width — number (px) or CSS length. Default "100%". */
  w?: number | string;
  /** Height — number (px) or CSS length. Default 12. */
  h?: number | string;
  /** Corner radius (px). Default 6. */
  radius?: number;
  style?: CSSProperties;
}

/** A single shimmering block (a Box with the shimmer style). */
export function Skeleton({ w = "100%", h = 12, radius = 6, style }: SkeletonProps) {
  return <Box aria-hidden radius={radius} style={{ width: w, height: h, ...shimmer, ...style }} />;
}

/** A stack of shimmer lines (the last one short) — a text/paragraph placeholder. */
export function SkeletonText({ lines = 3, gap = 8, lineH = 11 }: { lines?: number; gap?: number; lineH?: number }) {
  return (
    <Box style={{ display: "flex", flexDirection: "column", gap }}>
      {Array.from({ length: lines }).map((_, i) => (
        <Skeleton key={i} h={lineH} w={i === lines - 1 ? "60%" : "100%"} />
      ))}
    </Box>
  );
}

/** A block sized like a chart/graph — a shimmer rectangle at the chart's height. */
export function SkeletonChart({ height = 130 }: { height?: number }) {
  return <Skeleton w="100%" h={height} radius={8} />;
}

// MasterDetail — the first Layouts-tier template (#2197/#2198): the standardized list+detail page
// skeleton. A fixed-width bordered scroll RAIL (the master list/nav) + a flex:1 scroll DETAIL, under
// an optional full-width TOOLBAR. It owns the rail width/border/scroll + detail scroll/padding by
// construction, so every list page looks and behaves identically and a page becomes just
// `<MasterDetail rail={…} detail={…} />`. Sits on the layout primitives (Box/Row/Stack) in the same
// inline-style/token idiom; the escape hatches (railWidth/railPad/detailPad/railStyle/detailStyle)
// cover the rare deliberate difference — needing many is the signal a page is a DIFFERENT template.
//
// `resizable` (#2209) opts into a drag-resizable rail (a `.resize-x` splitter, backed by useDragResize)
// bounded by railMin/railMax, with railWidth as the starting size — for the pages that want it (GitHub
// repos). The default stays a fixed rail, so existing call sites are unaffected.
import type { CSSProperties, ReactNode } from "react";
import { Box } from "@/shared/ui/layout/Box";
import { Row } from "@/shared/ui/layout/Row";
import { Stack } from "@/shared/ui/layout/Stack";
import type { Space } from "@/shared/ui/layout/space";
import { useDragResize } from "@/shared/hooks/useDragResize";

export interface MasterDetailProps {
  /** The master column — the list/nav rail. */
  rail: ReactNode;
  /** The detail column — the selected item's editor/view. */
  detail: ReactNode;
  /** Optional full-width toolbar/header above both columns (search, filters, actions). */
  toolbar?: ReactNode;
  /** Fixed rail width in px (the starting width when `resizable`). Default 240. */
  railWidth?: number;
  /** Rail inner padding — a space rung or [block, inline]. Default 14. */
  railPad?: Space | [Space, Space];
  /** Detail inner padding. Default 20. */
  detailPad?: Space | [Space, Space];
  /** Opt into a drag-resizable rail (a `.resize-x` splitter between rail and detail). Default false. */
  resizable?: boolean;
  /** Min rail width when `resizable`. Default 160. */
  railMin?: number;
  /** Max rail width when `resizable`. Default 460. */
  railMax?: number;
  /** Escape hatch for a deliberate rail override (e.g. a canvas background). */
  railStyle?: CSSProperties;
  /** Escape hatch for a deliberate detail override. */
  detailStyle?: CSSProperties;
  /** Extra class on the root (a page scoping hook). */
  className?: string;
}

export function MasterDetail({
  rail, detail, toolbar,
  railWidth = 240, railPad = 14, detailPad = 20,
  resizable = false, railMin = 160, railMax = 460,
  railStyle, detailStyle, className,
}: MasterDetailProps) {
  // Always call the hook (rules of hooks); its live size only drives the rail when `resizable`.
  const drag = useDragResize({ initial: railWidth, min: railMin, max: railMax, axis: "x" });
  const width = resizable ? drag.size : railWidth;
  return (
    // Fills the <Screen> body; the toolbar (if any) sits above the two scrolling columns.
    <Stack gap={0} className={className} style={{ flex: 1, minHeight: 0, overflow: "hidden" }}>
      {toolbar}
      <Row gap={0} align="stretch" style={{ flex: 1, minHeight: 0, overflow: "hidden" }}>
        <Box pad={railPad} style={{
          flex: `0 0 ${width}px`, width, overflowY: "auto",
          borderRight: "1px solid var(--border-soft)", ...railStyle,
        }}>
          {rail}
        </Box>
        {/* The `.resize-x` grabber is a thin transparent strip after the rail's border (visible on hover). */}
        {resizable && <Box className="resize-x" {...drag.handleProps} title="Drag to resize" />}
        {/* Flex column so a centered empty-state (flex:1) fills, and scrolling content sizes right. */}
        <Box pad={detailPad} style={{
          flex: 1, minWidth: 0, overflow: "auto", display: "flex", flexDirection: "column", ...detailStyle,
        }}>
          {detail}
        </Box>
      </Row>
    </Stack>
  );
}

// SplitView — the Layouts-tier template for a two-pane split page (#2197 slice 2). A flexing PRIMARY
// pane beside (or above) a fixed-size, drag-resizable SECONDARY pane, with an optional full-width
// TOOLBAR. It owns the frame — the split direction, the divider border, the splitter wiring + its
// bounds — so a split page brings only its two pane contents. The canonical consumer is the Planner
// session (terminal PRIMARY + inspector SECONDARY); it generalizes the hand-rolled terminal/inspector
// split. Distinct from MasterDetail (whose fixed-width rail comes FIRST): here the resized pane is the
// SECOND one and the PRIMARY flexes to fill, so the splitter drives the trailing pane (invert).
//
// Sits on the layout primitives (Box/Row/Stack) in the same inline-style/token idiom. The escape
// hatches (secondaryMin/secondaryMax, divider, primaryStyle/secondaryStyle) cover the rare deliberate
// difference — needing many is the signal a page is a DIFFERENT template.
import type { CSSProperties, ReactNode } from "react";
import { Box } from "@/shared/ui/layout/Box";
import { Row } from "@/shared/ui/layout/Row";
import { Stack } from "@/shared/ui/layout/Stack";
import { useDragResize } from "@/shared/hooks/useDragResize";

export interface SplitViewProps {
  /** The flexing pane — fills the remaining space (terminal, editor, main content). */
  primary: ReactNode;
  /** The fixed-size, drag-resizable pane — the trailing side (inspector, sidebar, detail). */
  secondary: ReactNode;
  /** Split direction. "horizontal" (default) → side by side; "vertical" → primary above secondary. */
  orientation?: "horizontal" | "vertical";
  /** Opt out of the drag splitter for a fixed secondary. Default true. */
  resizable?: boolean;
  /** Secondary size in px (width when horizontal, height when vertical) — the starting size. Default 340. */
  secondarySize?: number;
  /** Min secondary size when resizable. Default 200. */
  secondaryMin?: number;
  /** Max secondary size when resizable. Default 640. */
  secondaryMax?: number;
  /** Optional full-width toolbar/header above the split (title, actions). */
  toolbar?: ReactNode;
  /** Draw the 1px divider border between the two panes. Default true. */
  divider?: boolean;
  /** Escape hatch for a deliberate primary override. */
  primaryStyle?: CSSProperties;
  /** Escape hatch for a deliberate secondary override. */
  secondaryStyle?: CSSProperties;
  /** Extra class on the root (a page scoping hook). */
  className?: string;
  /** Escape hatch for a deliberate root override (e.g. a top divider seam). */
  style?: CSSProperties;
}

export function SplitView({
  primary, secondary, orientation = "horizontal", resizable = true,
  secondarySize = 340, secondaryMin = 200, secondaryMax = 640,
  toolbar, divider = true, primaryStyle, secondaryStyle, className, style,
}: SplitViewProps) {
  const horizontal = orientation === "horizontal";
  // The secondary sits AFTER the splitter, so it grows as the pointer moves back toward the primary
  // (left/up) — invert the delta, like the GraphCanvas inspector.
  const drag = useDragResize({
    initial: secondarySize, min: secondaryMin, max: secondaryMax,
    axis: horizontal ? "x" : "y", invert: true,
  });
  const size = resizable ? drag.size : secondarySize;
  // The divider lives on the primary's trailing edge (right when horizontal, bottom when vertical);
  // when resizable the splitter strip already visually separates, so keep the border for a crisp seam.
  const primaryBorder = divider
    ? (horizontal ? { borderRight: "1px solid var(--border-soft)" } : { borderBottom: "1px solid var(--border-soft)" })
    : {};
  const Split = horizontal ? Row : Stack;

  const body = (
    <Split gap={0} align="stretch" style={{ flex: 1, minHeight: 0, minWidth: 0, overflow: "hidden" }}>
      {/* Flex pane — fills the remaining axis, clips its own content. */}
      <Box style={{
        flex: 1, minWidth: 0, minHeight: 0, display: "flex", flexDirection: "column",
        overflow: "hidden", ...primaryBorder, ...primaryStyle,
      }}>
        {primary}
      </Box>
      {/* The splitter grabber (thin transparent strip, visible on hover); axis-appropriate class. */}
      {resizable && <Box className={horizontal ? "resize-x" : "resize-y"} {...drag.handleProps} title="Drag to resize" />}
      {/* Fixed/resized trailing pane. */}
      <Box style={{
        flex: `0 0 ${size}px`, ...(horizontal ? { width: size } : { height: size }),
        minWidth: 0, minHeight: 0, display: "flex", flexDirection: "column",
        overflow: "hidden", ...secondaryStyle,
      }}>
        {secondary}
      </Box>
    </Split>
  );

  // Fills the <Screen> body; the toolbar (if any) sits above the split, matching MasterDetail.
  return (
    <Stack gap={0} className={className} style={{ flex: 1, minHeight: 0, overflow: "hidden", ...style }}>
      {toolbar}
      {body}
    </Stack>
  );
}

