components.source:
// RecordPage — the Pages-tier composition for KEY-VALUE-shaped data (#2508, completing the #2505
// page-per-shape set): the complete record-detail page for ONE keyed record, built strictly from kit
// components. A titled IDENTITY header (PageHeader → Box + SectionHeader: title + optional status
// Chip beside it, subtitle in the hint slot, an actions slot), grouped KeyValueList sections — each a
// SectionLabel over the key-value archetype (#2475) — and an optional side column (facts, related
// items) in the #2505 detail-column idiom. Pure/presentational — the typed `sections` in via props
// are the whole data source; no selection machinery (the page renders one record).
import type { ReactNode } from "react";
import { Box } from "@/shared/ui/layout/Box";
import { Row } from "@/shared/ui/layout/Row";
import { Stack } from "@/shared/ui/layout/Stack";
import { SectionLabel } from "@/shared/ui/layout/SectionLabel";
import { Chip, type ChipTone } from "@/shared/ui/data/Chip";
import { KeyValueList, type KeyValueItem } from "@/shared/ui/data/KeyValueList";
import { EmptyState } from "@/shared/ui/feedback/EmptyState";
import { PageHeader } from "./pageHeader";

/** One labelled group of the record's fields — a SectionLabel over a KeyValueList. */
export interface RecordSection {
  label: string;
  /** The group's { k, v } rows, in display order. */
  entries: KeyValueItem[];
}

export interface RecordPageProps {
  /** The record's identity — the page title (the header bar). */
  title: ReactNode;
  /** Dimmed identity sub-text after the title (the header hint slot). */
  subtitle?: ReactNode;
  /** A status Chip label rendered beside the title (e.g. "running", "archived"). */
  status?: string;
  /** Status Chip tone. Default "neutral". */
  statusTone?: ChipTone;
  /** Right-aligned header actions (edit, open, delete). */
  actions?: ReactNode;
  /** The record's field groups, in display order. */
  sections: RecordSection[];
  /** Optional side column (facts, related items) beside the sections. */
  aside?: ReactNode;
  /** Side column width in px. Default 300. */
  asideWidth?: number;
  /** Extra class on the root (a page scoping hook). */
  className?: string;
}

export function RecordPage({
  title, subtitle, status, statusTone = "neutral", actions,
  sections, aside, asideWidth = 300, className,
}: RecordPageProps) {
  const heading = status != null ? (
    <Row gap={8} inline>
      {title}
      <Chip size="xs" tone={statusTone}>{status}</Chip>
    </Row>
  ) : title;

  return (
    <Stack gap={0} className={className} style={{ flex: 1, minHeight: 0, overflow: "hidden" }}>
      <PageHeader title={heading} hint={subtitle} toolbar={actions} />
      <Row gap={0} align="stretch" style={{ flex: 1, minHeight: 0 }}>
        <Box pad={16} style={{ flex: 1, minWidth: 0, overflowY: "auto" }}>
          {sections.length > 0 ? (
            <Stack gap={20}>
              {sections.map((s) => (
                <Stack key={s.label} gap={10}>
                  <SectionLabel>{s.label}</SectionLabel>
                  <KeyValueList items={s.entries} />
                </Stack>
              ))}
            </Stack>
          ) : (
            <EmptyState iconVariant="dashed" icon="▤" size="sm" title="No fields yet"
              description="Sections appear here as the record's fields fill in." />
          )}
        </Box>
        {aside != null && (
          <Box pad={16} style={{ width: asideWidth, flex: "none", minWidth: 0, overflowY: "auto", borderLeft: "1px solid var(--border-soft)" }}>
            {aside}
          </Box>
        )}
      </Row>
    </Stack>
  );
}

runtime.shared/hooks/useDragResize.ts:
import { useCallback, useRef, useState, type PointerEvent as ReactPointerEvent } from "react";
import { clamp } from "@/shared/lib/core/math";

interface DragResizeOptions {
  /** Starting size in px. */
  initial: number;
  /** Lower bound in px. */
  min: number;
  /** Upper bound in px. */
  max: number;
  /** Which axis the handle drags along. */
  axis: "x" | "y";
  /**
   * Invert the delta. Use when the resized panel sits *after* the handle along
   * the axis (e.g. a right-hand panel grows as the pointer moves left).
   */
  invert?: boolean;
}

/**
 * Drag-to-resize state for a splitter handle. Spread `handleProps` onto the
 * divider element; `size` is the live, clamped dimension to apply to the panel.
 *
 * Uses pointer capture on the handle so the drag keeps tracking even when the
 * cursor leaves the thin divider — no global listeners to register or clean up.
 */
export function useDragResize({ initial, min, max, axis, invert = false }: DragResizeOptions) {
  const [size, setSize] = useState(() => clamp(initial, min, max));
  // Pointer position + panel size captured at drag start; null when not dragging.
  const start = useRef<{ pos: number; size: number } | null>(null);

  const onPointerDown = useCallback((e: ReactPointerEvent) => {
    e.preventDefault();
    (e.currentTarget as Element).setPointerCapture?.(e.pointerId);
    start.current = { pos: axis === "x" ? e.clientX : e.clientY, size };
  }, [axis, size]);

  const onPointerMove = useCallback((e: ReactPointerEvent) => {
    if (!start.current) return;
    const cur = axis === "x" ? e.clientX : e.clientY;
    const delta = (cur - start.current.pos) * (invert ? -1 : 1);
    setSize(clamp(start.current.size + delta, min, max));
  }, [axis, invert, min, max]);

  const onPointerUp = useCallback((e: ReactPointerEvent) => {
    start.current = null;
    (e.currentTarget as Element).releasePointerCapture?.(e.pointerId);
  }, []);

  return { size, setSize, handleProps: { onPointerDown, onPointerMove, onPointerUp } };
}

runtime.shared/hooks/useModalDismiss.ts:
// useModalDismiss (#1541) — the Escape-to-close + overlay-click-to-close pattern that was
// hand-rolled inline across the app's modals (`Dialog.tsx` is the reference implementation).
//
//  - useModalDismiss(onClose, { enabled }) — a window keydown Escape listener → onClose, with
//    cleanup on unmount / deps-change. `enabled` (default true) gates it, e.g. `{ enabled: !busy }`.
//  - overlayDismiss(onClose?) — an onMouseDown/onClick handler that fires onClose ONLY when the
//    event hits the overlay itself (`e.target === e.currentTarget`), so clicks on the inner card
//    don't dismiss. Pass `undefined` (e.g. while busy/deleting) to disable dismissal entirely.

import { useEffect, type MouseEvent } from "react";

export function useModalDismiss(onClose: () => void, opts?: { enabled?: boolean }): void {
  const enabled = opts?.enabled ?? true;
  useEffect(() => {
    if (!enabled) return;
    const onKey = (e: KeyboardEvent) => { if (e.key === "Escape") onClose(); };
    window.addEventListener("keydown", onKey);
    return () => window.removeEventListener("keydown", onKey);
  }, [onClose, enabled]);
}

/** An overlay click/mousedown handler that dismisses only when the overlay itself is the target.
 *  `onClose === undefined` makes it a no-op (use for a busy/locked modal). */
export function overlayDismiss(onClose?: () => void) {
  return (e: MouseEvent) => {
    if (onClose && e.target === e.currentTarget) onClose();
  };
}

runtime.shared/lib/core/configOverrides.ts:
// #2047 — frontend runtime config loading (parity of the backend's P2). The app's config surfaces
// (blueprints / roles / skills / stage defs / taxonomies) are Vite-embedded via `import.meta.glob` +
// direct `@data/*` imports as the DEFAULT; this module overlays the runtime config dir
// (~/.base-studio-code/config/) over those defaults, primed at boot BEFORE the config modules build
// their consts — so editing a `@data` file under the config dir takes effect on next launch, no rebuild.
//
// Fail-safe by design: `overrides` stays empty in browser-dev (no Tauri) or if the fetch fails, so
// every overlay falls back to the embedded default and behavior is unchanged without a backend.

/** The primed config-dir files (`rel-path → contents`). Empty until `primeConfigOverrides` resolves. */
let overrides: Record<string, string> = {};
let primed = false;

/** Fetch the config-dir files once, before App (and the config modules) are imported. Must be awaited
 *  in the entry (`main.tsx`) ahead of the dynamic `App` import. No-ops safely on any failure. */
export async function primeConfigOverrides(): Promise<void> {
  if (primed) return;
  primed = true;
  try {
    // Dynamic import so the pure `overlay*` consumers (deployEnv/sessionRoles/…) don't statically
    // pull in the Tauri API — only this boot-time primer touches it.
    const { invoke } = await import("@tauri-apps/api/core");
    const files = await invoke<Record<string, string>>("get_config_files");
    if (files && typeof files === "object") overrides = files;
  } catch {
    // No Tauri backend (browser dev) or a read failure — the embedded defaults stand.
  }
}

/** Overlay the config-dir copies over an eager `import.meta.glob` surface, matched by filename stem.
 *  Returns `[stem, parsedValue][]` (embedded order, overrides replacing in place; new files appended) —
 *  the caller shapes it into a Record or a values list. `dir` is the config-dir subdir (e.g. "stages"). */
export function overlayGlob<T>(dir: string, embedded: Record<string, { default: T }>): [string, T][] {
  const out = new Map<string, T>(); // stem → value
  for (const [path, mod] of Object.entries(embedded)) out.set(stem(path), mod.default);
  for (const [rel, content] of Object.entries(overrides)) {
    if (dirOf(rel) !== dir) continue;
    const parsed = tryParse<T>(content);
    if (parsed !== undefined) out.set(stem(rel), parsed);
  }
  return [...out.entries()];
}

/** Overlay a single direct-import `@data` file: the config-dir copy parsed, else the embedded default.
 *  `rel` is the config-dir-relative path (e.g. "planner/blueprint-meta.json"). */
export function overlayFile<T>(rel: string, embedded: T): T {
  const content = overrides[rel];
  if (content === undefined) return embedded;
  return tryParse<T>(content) ?? embedded;
}

/** Overlay a single RAW (non-JSON) `@data` file — e.g. a markdown prompt/protocol imported with
 *  `?raw`: the config-dir copy's text verbatim if present, else the embedded default. The raw analogue
 *  of {@link overlayFile} (no parse), giving markdown surfaces the same edit-without-rebuild parity the
 *  Rust `load_str` gives them backend-side. */
export function overlayRaw(rel: string, embedded: string): string {
  const content = overrides[rel];
  return content === undefined ? embedded : content;
}

/** Test-only: reset the primed state so a spec can re-prime with a fresh mock. */
export function resetConfigOverridesForTest(): void {
  overrides = {};
  primed = false;
}

function basename(p: string): string { return p.slice(p.lastIndexOf("/") + 1); }
function stem(p: string): string { const b = basename(p); return b.endsWith(".json") ? b.slice(0, -5) : b; }
function dirOf(rel: string): string { const i = rel.lastIndexOf("/"); return i < 0 ? "" : rel.slice(0, i); }
function tryParse<T>(s: string): T | undefined { try { return JSON.parse(s) as T; } catch { return undefined; } }

runtime.shared/lib/core/format.ts:
// Shared presentation helpers (#1471) — feature-agnostic, pure. Used by the GitHub and
// planner summaries. Extracted to remove byte-identical copies in ProjectsSummary +
// GitHubSummary.

/**
 * A coarse "time since" label from an ISO timestamp: `5s ago` / `3m ago` / `2h ago` /
 * `4d ago` / `2mo ago`. Returns "" for an empty, non-finite, or future timestamp.
 */
export function timeAgo(iso: string): string {
  return sinceLabel(iso, " ago");
}

/** Compact variant of {@link timeAgo} without the trailing " ago": `5s` / `4d` / `2mo`. */
export function timeAgoShort(iso: string): string {
  return sinceLabel(iso, "");
}

function sinceLabel(iso: string, suffix: string): string {
  if (!iso) return "";
  const s = Math.floor((Date.now() - new Date(iso).getTime()) / 1000);
  if (!isFinite(s) || s < 0) return "";
  if (s < 60) return `${s}s${suffix}`;
  const m = Math.floor(s / 60); if (m < 60) return `${m}m${suffix}`;
  const h = Math.floor(m / 60); if (h < 24) return `${h}h${suffix}`;
  const d = Math.floor(h / 24); if (d < 30) return `${d}d${suffix}`;
  return `${Math.floor(d / 30)}mo${suffix}`;
}

/** A coarse "time since" label from epoch millis; "—" when non-positive. */
export function timeAgoMs(ms: number): string {
  return ms > 0 ? timeAgo(new Date(ms).toISOString()) : "—";
}

/**
 * A stable 32-bit unsigned hash of a string (`h = h*31 + charCode`, truncated to
 * uint32 each step). Deterministic, so the same string always hashes the same — the
 * shared core behind the continuous-hue color helpers ({@link loginColor} + the fleet
 * board's profile color). Callers map the hash to their own space (e.g. `% 360` for a hue).
 *
 * Note: `hueFor` (per-step `% 360`) and the discrete `avatarColor` (per-step `& 0xffff`)
 * use *different* reductions and are intentionally NOT built on this — they'd produce
 * different colors.
 */
export function hashString(s: string): number {
  let h = 0;
  for (let i = 0; i < s.length; i++) h = (h * 31 + s.charCodeAt(i)) >>> 0;
  return h;
}

/** A stable oklch color hashed from a login, so the same user always renders the same hue. */
export function loginColor(login: string): string {
  return `oklch(0.68 0.12 ${hashString(login) % 360})`;
}

/** A deterministic hue (0–359) hashed from a string — a tile/category accent. */
export function hueFor(s: string): number {
  let h = 0;
  for (let i = 0; i < s.length; i++) h = (h * 31 + s.charCodeAt(i)) % 360;
  return h;
}

/** Human-readable byte size: `0 B` / `1.5 KB` / `2.3 GB` / `1.1 TB`. */
export function fmtBytes(n: number): string {
  if (n <= 0) return "0 B";
  const u = ["B", "KB", "MB", "GB", "TB"];
  const i = Math.min(u.length - 1, Math.floor(Math.log(n) / Math.log(1024)));
  return `${(n / Math.pow(1024, i)).toFixed(i === 0 ? 0 : 1)} ${u[i]}`;
}

/**
 * Truncate `s` with a `…` when it exceeds `max` characters (#2421 — the one home for the
 * five hand-rolled ellipsis chains).
 *
 * `keep` is how many characters survive before the ellipsis and defaults to `max` — the
 * "hard cap" shape (`s.slice(0, max) + "…"` only when longer, e.g. an issue body preview).
 * Pass a smaller `keep` for the "display budget" shape the label sites use, where the
 * truncated form must fit the same budget as the untruncated one (e.g. `truncate(s, 20, 18)`).
 */
export function truncate(s: string, max: number, keep = max): string {
  return s.length > max ? `${s.slice(0, keep)}…` : s;
}

/**
 * Kebab-case slug: lowercase, every run of non-alphanumerics collapsed to a single `-`,
 * edge dashes stripped, optionally capped at `max` characters (#2421 — the one home for the
 * planner/source/DesignsWorkbench copies). Returns `""` for input with no alphanumerics — callers
 * that need a fallback apply their own (`slugify(x, 40) || "source"`).
 *
 * NOT {@link sanitizeProjectKey} (../core/projectPaths.ts): that mirrors the Rust backend
 * byte-for-byte (keeps case, `_` replacement, cap 80) and must not change; this is the
 * display/id kebab-case convention.
 *
 * Note: the cap is applied AFTER edge-stripping (matching every former copy), so a capped
 * slug can still end in a `-` when the cut lands on a word boundary.
 */
export function slugify(s: string, max?: number): string {
  const slug = s.toLowerCase().replace(/[^a-z0-9]+/g, "-").replace(/^-+|-+$/g, "");
  return max != null ? slug.slice(0, max) : slug;
}

/** Local wall-clock `HH:MM` (or `HH:MM:SS` with `{ seconds: true }`) for an epoch-ms
 *  timestamp; `—` for null (#2421 — automations' HH:MM + MCP Analytics' HH:MM:SS unified). */
export function fmtClock(ms: number | null, opts: { seconds?: boolean } = {}): string {
  if (ms == null) return "—";
  const d = new Date(ms);
  const hm = `${String(d.getHours()).padStart(2, "0")}:${String(d.getMinutes()).padStart(2, "0")}`;
  return opts.seconds ? `${hm}:${String(d.getSeconds()).padStart(2, "0")}` : hm;
}

/** Local `YYYY-MM-DD` for an epoch-ms timestamp — the daily-bucket key the telemetry
 *  aggregators and their charts share (#2421; was byte-identical in hook/mcp telemetry). */
export function dayKey(ts: number): string {
  const d = new Date(ts);
  return `${d.getFullYear()}-${String(d.getMonth() + 1).padStart(2, "0")}-${String(d.getDate()).padStart(2, "0")}`;
}

