runtime.shared/lib/graph/cycles.ts:
// Cycle detection (#2217, graph-core epic #2214) — the shared primitives the graphs use to find cycles
// in a directed graph. Two flavours, matching what the features already do:
//   • findBackEdges — DFS (white/grey/black) back-edge detection: finds ANY-length cycle and returns
//     the edges that close one. Used for topological layering (exclude back-edges so a cycle can't
//     explode the layout) and to flag coordination deadlocks. This is the relationship graph's algorithm.
//   • mutualPairs — the 2-cycle special case (a↔b): the cheap "mutual dependency" check the Glance
//     network surfaces as coordination hazards.
// Both are pure; the caller pre-filters to whichever edge subset is order-bearing.
import type { GraphEdge } from "./types";

/**
 * DFS back-edge detection over `edges` restricted to `nodeIds`. Returns the set of edge ids that close
 * a cycle (grey-target back-edges) and whether any cycle exists. Nodes are visited in `nodeIds` order
 * and each node's out-edges in `edges` order, so the result is deterministic.
 */
export function findBackEdges(nodeIds: readonly string[], edges: readonly GraphEdge[]): { backEdgeIds: Set<string>; hasCycle: boolean } {
  const idSet = new Set(nodeIds);
  const adj = new Map<string, { to: string; id: string }[]>(nodeIds.map((i) => [i, []]));
  for (const e of edges) {
    if (idSet.has(e.from) && idSet.has(e.to)) adj.get(e.from)!.push({ to: e.to, id: e.id });
  }
  const color = new Map<string, 0 | 1 | 2>(); // 0 white · 1 grey (on stack) · 2 black
  const backEdgeIds = new Set<string>();
  let hasCycle = false;
  const dfs = (n: string) => {
    color.set(n, 1);
    for (const { to, id } of adj.get(n) ?? []) {
      const c = color.get(to) ?? 0;
      if (c === 1) { hasCycle = true; backEdgeIds.add(id); } // back-edge → a cycle
      else if (c === 0) dfs(to);
    }
    color.set(n, 2);
  };
  for (const i of nodeIds) if ((color.get(i) ?? 0) === 0) dfs(i);
  return { backEdgeIds, hasCycle };
}

/**
 * Mutual pairs (a↔b) — every pair of nodes with edges in both directions. Returns the pairs (each once,
 * `from < to`), the ids of ALL edges in a mutual pair (both directions), and the node ids involved.
 */
export function mutualPairs(edges: readonly GraphEdge[]): { pairs: [string, string][]; edgeIds: Set<string>; nodeIds: Set<string> } {
  const pairs: [string, string][] = [];
  const edgeIds = new Set<string>();
  const nodeIds = new Set<string>();
  for (const a of edges) for (const b of edges) {
    if (a.from === b.to && a.to === b.from && a.from < a.to) {
      edgeIds.add(a.id); edgeIds.add(b.id);
      pairs.push([a.from, a.to]);
      nodeIds.add(a.from); nodeIds.add(a.to);
    }
  }
  return { pairs, edgeIds, nodeIds };
}

runtime.shared/lib/graph/edgePath.ts:
// Shared edge geometry (#2222, graph design-language #2221) — the ONE line-type every graph draws its
// edges with: a cubic bezier + a filled-triangle arrowhead + a label midpoint, in a shared grammar.
// Only the ROUTING (where the curve meets each card) is layout-dependent (#2226), via `routing`:
//   • "anchor" — perimeter-anchor: leaves each card at the point on its border facing the other card.
//     Right for FREE / ORGANIC layouts (the Org designer's force graph).
//   • "ports"  — side ports: leaves the right (or left) edge at the vertical middle with horizontal
//     control handles. Right for LAYERED left→right graphs (Glance's dependency DAG) — clean columnar
//     flow. (Restores Glance's pre-#2222 geometry; the perimeter router read messy on a layered graph.)
// Both share the arrowhead + label + `bow` (perpendicular separation for parallel/bidirectional/cycle
// edges) + `doubleEnded` (a source arrow for bidirectional relationships). Pure.

export interface EdgeBox { x: number; y: number; w: number; h: number }

export type EdgeRouting = "anchor" | "ports";

export interface GraphEdgeOpts {
  /** Where the curve meets each card. Default "anchor" (perimeter); "ports" for layered graphs. */
  routing?: EdgeRouting;
  /** Perpendicular bow (px) so parallel/bidirectional/cycle edges separate. Default 0. */
  bow?: number;
  /** ("anchor" only) how far short of the target border the curve ends, for the arrow. Default 9. */
  endGap?: number;
  /** Arrowhead length (px); half-width ≈ 0.58×. Default 9. */
  arrowSize?: number;
  /** Also draw an arrowhead at the source (bidirectional). Default false. */
  doubleEnded?: boolean;
}

export interface GraphEdgeGeom {
  /** The cubic-bezier path `d`. */
  d: string;
  /** Filled-triangle arrowhead path at the target border. */
  arrow: string;
  /** Filled-triangle arrowhead at the source border (only when `doubleEnded`). */
  arrowStart?: string;
  /** The curve midpoint — where an edge label pill sits. */
  labelX: number;
  labelY: number;
}

const f = (v: number): number => Math.round(v * 10) / 10;

/** The point on box `a`'s perimeter along the ray toward (tx,ty), with a 3px outset so the line clears
 *  the border. (The Org designer's `anchor` — exported since #2418 replaced org's byte-identical copy;
 *  its feature barrel re-exports this one.) */
export function anchor(a: EdgeBox, tx: number, ty: number): [number, number] {
  const cx = a.x + a.w / 2, cy = a.y + a.h / 2, dx = tx - cx, dy = ty - cy;
  const hw = a.w / 2 + 3, hh = a.h / 2 + 3;
  const sx = dx === 0 ? 1e9 : hw / Math.abs(dx);
  const sy = dy === 0 ? 1e9 : hh / Math.abs(dy);
  const s = Math.min(sx, sy);
  return [cx + dx * s, cy + dy * s];
}

/** A filled-triangle arrow with its tip at (tipx,tipy), pointing along `ang`. */
function arrowPath(tipx: number, tipy: number, ang: number, len: number): string {
  const w = len * 0.58;
  const bx = tipx - Math.cos(ang) * len, by = tipy - Math.sin(ang) * len;
  const nx = -Math.sin(ang), ny = Math.cos(ang);
  return `M ${f(tipx)} ${f(tipy)} L ${f(bx + nx * w)} ${f(by + ny * w)} L ${f(bx - nx * w)} ${f(by - ny * w)} Z`;
}

/** Assemble the geometry from the four control points (source, two handles, arrow tip). Shared by both
 *  routers: the curve ends at `tip`, the arrow sits there, the label is the cubic midpoint. */
function assemble(p1x: number, p1y: number, c1x: number, c1y: number, c2x: number, c2y: number, tipx: number, tipy: number, arrowSize: number, doubleEnded: boolean): GraphEdgeGeom {
  const d = `M ${f(p1x)} ${f(p1y)} C ${f(c1x)} ${f(c1y)} ${f(c2x)} ${f(c2y)} ${f(tipx)} ${f(tipy)}`;
  // The cubic's midpoint (t=0.5) via the Bernstein weights (1/8, 3/8, 3/8, 1/8).
  const labelX = 0.125 * p1x + 0.375 * c1x + 0.375 * c2x + 0.125 * tipx;
  const labelY = 0.125 * p1y + 0.375 * c1y + 0.375 * c2y + 0.125 * tipy;
  const arrow = arrowPath(tipx, tipy, Math.atan2(tipy - c2y, tipx - c2x), arrowSize);
  const arrowStart = doubleEnded ? arrowPath(p1x, p1y, Math.atan2(p1y - c1y, p1x - c1x), arrowSize) : undefined;
  return { d, arrow, arrowStart, labelX, labelY };
}

/** Perimeter-anchor routing — for free/organic layouts. Byte-identical to the Org designer's geometry. */
function anchorEdge(from: EdgeBox, to: EdgeBox, opts: GraphEdgeOpts): GraphEdgeGeom {
  const bow = opts.bow ?? 0, endGap = opts.endGap ?? 9, arrowSize = opts.arrowSize ?? 9;
  const acx = from.x + from.w / 2, acy = from.y + from.h / 2, bcx = to.x + to.w / 2, bcy = to.y + to.h / 2;
  const [p1x, p1y] = anchor(from, bcx, bcy);
  const [b2x, b2y] = anchor(to, acx, acy);       // the target border point — the arrow tip
  const dx0 = b2x - p1x, dy0 = b2y - p1y, L = Math.hypot(dx0, dy0) || 1;
  const p2x = b2x - (dx0 / L) * endGap;          // curve ends short of the border
  const p2y = b2y - (dy0 / L) * endGap;
  const dx = p2x - p1x, dy = p2y - p1y;
  const nx = -dy / L, ny = dx / L;
  const c1x = p1x + dx * 0.35 + nx * bow, c1y = p1y + dy * 0.35 + ny * bow;
  const c2x = p1x + dx * 0.65 + nx * bow, c2y = p1y + dy * 0.65 + ny * bow;
  // NB: the arrow tip is the border point; the curve ends short of it (p2).
  return {
    ...assemble(p1x, p1y, c1x, c1y, c2x, c2y, p2x, p2y, arrowSize, !!opts.doubleEnded),
    arrow: arrowPath(b2x, b2y, Math.atan2(p2y - c2y, p2x - c2x), arrowSize),
  };
}

/** Side-port routing — for layered left→right graphs. Leaves the right (or left) edge at the vertical
 *  middle with horizontal control handles, giving a clean columnar flow. Restores Glance's geometry. */
function portsEdge(from: EdgeBox, to: EdgeBox, opts: GraphEdgeOpts): GraphEdgeGeom {
  const bow = opts.bow ?? 0, arrowSize = opts.arrowSize ?? 9;
  const fRight = from.x < to.x;
  const p1x = from.x + (fRight ? from.w : 0), p1y = from.y + from.h / 2;
  const tLeftPort = to.x >= from.x;
  const tx = to.x + (tLeftPort ? 0 : to.w), ty = to.y + to.h / 2;   // target port — the arrow tip
  const k = Math.max(46, Math.abs(tx - p1x) * 0.5);
  const c1x = p1x + (fRight ? k : -k), c1y = p1y + bow;
  const c2x = tx + (tLeftPort ? -k : k), c2y = ty + bow;
  return assemble(p1x, p1y, c1x, c1y, c2x, c2y, tx, ty, arrowSize, !!opts.doubleEnded);
}

/** The shared line-type between two boxes; `routing` picks the router. See the module header. */
export function graphEdge(from: EdgeBox, to: EdgeBox, opts: GraphEdgeOpts = {}): GraphEdgeGeom {
  return opts.routing === "ports" ? portsEdge(from, to, opts) : anchorEdge(from, to, opts);
}

runtime.shared/lib/graph/layers.ts:
// Topological layering (#2214, graph-core epic) — the ONE longest-path layerer the graphs share. A
// dependency/coordination DAG flows across LAYERS: each node lands as deep as its longest incoming
// chain, so a source (no in-edges) sits at layer 0. The caller hands in a cycle-break set (the
// back-edges it already computed via `cycles.ts`, or its 2-cycle mutual pairs) so a loop can't diverge
// the layout. Pure; the callers own the layer→pixel PLACEMENT (Glance's grid, Relationship's swimlanes)
// — this only assigns the layer number.
import type { GraphEdge } from "./types";

/**
 * Longest-path topological layering. Assigns each node in `nodeIds` an integer layer so that for every
 * kept edge `from→to`, `layer[to] >= layer[from] + 1` — sources sit at layer 0 and each node lands as
 * deep as its longest incoming chain. Edges in `backEdgeIds` (the caller's cycle-break set), self-loops,
 * and edges touching an id outside `nodeIds` are ignored, so a cycle can't diverge the assignment. The
 * result is the DAG's unique longest-path layering, so it's independent of the relaxation order (and
 * identical to a Kahn / memoized-DFS layerer over the same acyclic edge set).
 *
 * Edge direction is "from → deeper": a node points to the nodes that must sit BELOW it. A "depends-on"
 * DAG — where the dependency should sit at a LOWER layer than its dependent — reverses its edges before
 * calling (see Glance's `buildGraph`).
 */
export function layerDag(
  nodeIds: readonly string[],
  edges: readonly GraphEdge[],
  backEdgeIds?: ReadonlySet<string>,
): Record<string, number> {
  const idSet = new Set(nodeIds);
  const kept = edges.filter(
    (e) => e.from !== e.to && idSet.has(e.from) && idSet.has(e.to) && !backEdgeIds?.has(e.id),
  );
  const layer: Record<string, number> = {};
  for (const id of nodeIds) layer[id] = 0;
  // Relax to the fixpoint: the longest path on a DAG spans ≤ nodeIds.length edges, so that many sweeps
  // always converge; the `changed` guard usually breaks far sooner. Same result as Kahn — order-free.
  for (let iter = 0; iter <= nodeIds.length; iter++) {
    let changed = false;
    for (const e of kept) {
      if (layer[e.to] < layer[e.from] + 1) { layer[e.to] = layer[e.from] + 1; changed = true; }
    }
    if (!changed) break;
  }
  return layer;
}

runtime.shared/lib/graph/order.ts:
// Barycenter layer ordering (#2418, graph-core epic #2214) — the ONE crossing-reduction sweep the
// layered graphs share. Given a layer assignment (from `layerDag` or any layerer), order the nodes
// WITHIN each layer so each sits near the mean in-layer index of its neighbors — the classic Sugiyama
// barycenter heuristic. What VARIES per graph is tunable: the neighbor gathering (org pulls only from
// cross-layer hierarchy parents/children; Glance from every edge endpoint), the pass count, and the
// sweep discipline. Pure; the caller owns the layer→pixel placement.

export interface OrderLayersOpts {
  /** Barycenter sweeps over the whole layer set. Default 4. */
  passes?: number;
  /** How fresh the neighbor indexes are within one pass:
   *   • "sequential" (default) — sorting layer L reads the ALREADY re-sorted order of the layers
   *     sorted earlier in the same pass, so an improvement propagates immediately (org's discipline).
   *   • "snapshot" — every layer sorts against the order at the START of the pass (Glance's). */
  sweep?: "sequential" | "snapshot";
}

/**
 * Order the nodes within each layer by the barycenter heuristic: each layer is sorted by the mean
 * in-layer index of each node's neighbors; a node with no (known) neighbors keeps its current index.
 * The initial order is `nodeIds` order filtered per layer; ties keep the pre-sort order (stable sort).
 *
 * @param nodeIds Every node, in the initial (seed) order.
 * @param layerOf The layer assignment (e.g. `layerDag`'s).
 * @param neighborsOf The ids whose in-layer positions pull on a node — the caller's neighbor
 *   gathering. Multiplicity counts (a doubly-connected neighbor pulls twice); ids outside `nodeIds`
 *   are ignored.
 * @returns layer → its node ids in final order (layers in ascending order).
 */
export function orderLayers(
  nodeIds: readonly string[],
  layerOf: (id: string) => number,
  neighborsOf: (id: string) => readonly string[],
  opts: OrderLayersOpts = {},
): Map<number, string[]> {
  const passes = opts.passes ?? 4;
  const sweep = opts.sweep ?? "sequential";
  const layers = [...new Set(nodeIds.map(layerOf))].sort((a, b) => a - b);
  const order = new Map<number, string[]>(layers.map((l) => [l, nodeIds.filter((n) => layerOf(n) === l)]));
  const idx = new Map<string, number>();
  const reindex = (l: number) => order.get(l)!.forEach((n, i) => idx.set(n, i));
  layers.forEach(reindex);

  const bary = (n: string): number => {
    const neigh = neighborsOf(n).filter((m) => idx.has(m));
    if (neigh.length === 0) return idx.get(n)!;
    return neigh.reduce((s, m) => s + idx.get(m)!, 0) / neigh.length;
  };
  const sortLayer = (l: number, b: Map<string, number>) => {
    order.get(l)!.sort((x, y) => b.get(x)! - b.get(y)!);
    reindex(l);
  };

  for (let pass = 0; pass < passes; pass++) {
    if (sweep === "snapshot") {
      const b = new Map(nodeIds.map((n) => [n, bary(n)] as const));
      for (const l of layers) sortLayer(l, b);
    } else {
      for (const l of layers) sortLayer(l, new Map(order.get(l)!.map((n) => [n, bary(n)] as const)));
    }
  }
  return order;
}

